package nft

import (
	"chain/runtime"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/nt/grc721/v0"
)

// TokenURI returns the Settler image as an SVG data URI.
// Wallets such as Adena read TokenURI directly as the token image,
// so this must be the image itself. The metadata lives in TokenMetadata.
func TokenURI(tid grc721.TokenID) (string, error) {
	traits, err := TraitsOf(tid)
	if err != nil {
		return "", err
	}

	return nft.RenderDataURI(traits, nft.Options{Size: nft.CanonicalSize}), nil
}

// TokenMetadata returns a JSON string with the metadata of a Settler
// in the format the Adena wallet can understand.
func TokenMetadata(tid grc721.TokenID) (string, error) {
	traits, err := TraitsOf(tid)
	if err != nil {
		return "", err
	}

	var attrs string
	for i, attr := range traits.Attributes() {
		if i > 0 {
			attrs += ","
		}

		attrs += `{"traitType":"` + attr.Type + `","value":"` + attr.Value + `"}`
	}

	return `{"name":"Settler #` + string(tid) + `",` +
		`"description":"Soulbound gnome of the early settlers of Gno.land. ` + nft.Credits + `",` +
		`"image":"` + nft.RenderDataURI(traits, nft.Options{Size: nft.CanonicalSize}) + `",` +
		`"externalUrl":"` + ExternalURL(tid) + `",` +
		`"attributes":[` + attrs + `]}`, nil
}

// ExternalURL returns the URL to a Settler profile page.
func ExternalURL(tid grc721.TokenID) string {
	return "https://" + runtime.ChainDomain() + RealmPath + ":token/" + string(tid)
}

package nft

import (
	"chain"
	"chain/runtime"
	"crypto/merkle"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/bloom"
	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/mdalert/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	// Name is the NFT token's name.
	Name = "Settlers"

	// Symbol is the NFT token's symbol.
	Symbol = "SETTLER"

	// Capacity is the total number of Settlers that can be minted.
	capacity = 3000

	// Max nonce is how many gnomes are tried for a token before giving up,
	// when the ones that come out are already taken.
	maxNonce = 64

	// Max aunts is the longest proof accepted.
	maxAunts = 40
)

// ErrSoulbound is returned for operation that are not allowed on a soulbound NFT.
var ErrSoulbound = errors.New("settlers are soulbound, they can't be transferred or approved")

var (
	// Realm path is the path of this realm.
	RealmPath string

	// Notice is a realm-wide message the admin can post at any time, shown at the top of the page.
	// It never affects SVG, URI or Markdown, it is purely informational.
	Notice string

	// NoticeType is the style Notice is shown as.
	NoticeType mdalert.Type

	// Admin account for the realm.
	// This account is only valid to set snapshot params, once setted minting
	// can start and after the first NFT is minted the account is not allowed to change
	// snapshot params anymore.
	// It is always allowed to post or clear realm-wide notices.
	admin *ownable.Ownable

	// Supply cap is the number of Settlers that can be minted.
	supplyCap = capacity

	// Root is the Merkle root value.
	root []byte

	// Total is the total number of leaves of the list of elegible accounts.
	total int

	// Collection is the GRC721 token, it keeps the owners and balances and emits the standard events.
	collection *grc721.Token

	// Ledger is the writable side of the collection, only used to mint.
	ledger *grc721.PrivateLedger

	// Tokens has the packed traits of every token, by ID (zero-padded, so it is in mint order).
	tokens = bptree.NewBPTree32()

	// Claimed has the ID of the token for each account.
	claimed = bptree.NewBPTree32()

	// Seen traits has the packed traits of minted tokens to check that two Settlers are never the same.
	seenTraits = newTraitsFilter()
)

func init(cur realm) {
	RealmPath = strings.TrimPrefix(cur.PkgPath(), runtime.ChainDomain())
	admin = ownable.NewWithAddress(cur.Previous().Address())
	collection, ledger = newCollection(cur)
}

// Soulbound is a GRC721 extension that aborts any transfer of a Settler.
// The realm never exposes a teller that can write, so a transfer can't be started,
// this makes sure that it could never finish either.
type soulbound struct{}

func (soulbound) ExtensionKind() string                       { return "soulbound" }
func (soulbound) OnMint(address, grc721.TokenID)              {}
func (soulbound) OnTransfer(address, address, grc721.TokenID) { panic(ErrSoulbound) }
func (soulbound) OnBurn(grc721.TokenID)                       {}

// newCollection creates the GRC721 token of the Settlers.
func newCollection(cur realm) (*grc721.Token, *grc721.PrivateLedger) {
	tok, led := grc721.NewToken(Name, Symbol, 0, cur)
	led.RegisterExtension(soulbound{})
	return tok, led
}

// SetSnapshot opens the mint.
// It sets the Merkle root of the list of eligible accounts, in hex, and the
// number of accounts in the list. Only the owner can call it.
// It can be called again to correct a mistake until the first Settler is minted,
// from then on the list is frozen.
func SetSnapshot(cur realm, rootHex string, count int) {
	assertIsCurrent(cur)
	admin.AssertOwnedBy(cur.Previous().Address())

	if tokens.Size() > 0 {
		panic("the snapshot is frozen: Settlers were already minted")
	}

	bz, err := hex.DecodeString(rootHex)
	if err != nil || len(bz) != 32 {
		panic("the root must be 32 bytes in hex")
	}

	if count < 1 {
		panic("the list must have at least one account")
	}

	root = bz
	total = count
	chain.Emit(
		"SnapshotSet",
		"root", rootHex,
		"total", strconv.Itoa(count),
	)
}

// Admin returns the address of the admin account.
func Admin() address { return admin.Owner() }

// TransferAdmin makes another account the admin. Only the admin can call it.
func TransferAdmin(cur realm, newAdmin address) {
	assertIsCurrent(cur)
	if err := admin.TransferOwnership(0, cur, newAdmin); err != nil {
		panic(err)
	}
}

// SetNotice posts a realm-wide message, shown at the top of the page.
func SetNotice(cur realm, alertType mdalert.Type, msg string) {
	assertIsCurrent(cur)
	admin.AssertOwnedBy(cur.Previous().Address())
	assertIsValidAlertType(alertType)

	NoticeType = alertType
	Notice = msg
	chain.Emit("NoticeSet", "type", string(alertType))
}

// ClearNotice removes the current notice.
func ClearNotice(cur realm) {
	assertIsCurrent(cur)
	admin.AssertOwnedBy(cur.Previous().Address())

	NoticeType = ""
	Notice = ""
	chain.Emit("NoticeCleared")
}

// Mint mints a Settler to the caller and returns its ID.
//
// The proof shows that the caller is in the list of eligible accounts.
// Proof format is "<index>.<aunts>".
// Only user accounts can mint, either with a call or a run transaction, realms can't.
func Mint(cur realm, proof string) grc721.TokenID {
	assertIsCurrent(cur)
	if !cur.Previous().IsUser() {
		panic("only user accounts can mint")
	}

	if len(root) == 0 {
		panic("the mint is not open yet")
	}

	minted := tokens.Size()
	if minted >= supplyCap {
		panic("sold out")
	}

	caller := cur.Previous().Address()
	if claimed.Has(caller.String()) {
		panic("this account has already minted")
	}

	index, aunts, err := splitProof(proof)
	if err != "" {
		panic(err)
	}

	if !merkle.VerifySimpleProof(root, []byte(caller), index, total, aunts) {
		panic("the proof is not valid for this account: " + caller.String())
	}

	settlerID := minted + 1
	prefix := seedPrefix(caller, settlerID)

	var (
		packed    uint32
		packedKey string
	)
	for nonce := 0; ; nonce++ {
		if nonce == maxNonce {
			panic("could not find a new gnome, try again")
		}

		seed := hashSeed(prefix, nonce)
		traits := nft.NewTraits(seed)
		packed = nft.Pack(traits.Normalized())
		packedKey = strconv.FormatUint(uint64(packed), 10)
		if !seenTraits.ContainsString(packedKey) {
			break
		}
	}

	tid := tokenID(settlerID)
	if err := ledger.Mint(caller, tid); err != nil {
		panic(err)
	}

	tokens.Set(makeKey(settlerID), packed)
	seenTraits.AddString(packedKey)
	claimed.Set(caller.String(), tid)
	return tid
}

// Cap returns the number of Settlers that can be minted.
func Cap() int { return supplyCap }

// MerkleRoot returns the Merkle root of the list of eligible accounts, in hex.
func MerkleRoot() string { return hex.EncodeToString(root) }

// Total returns the number of eligible accounts in the list.
func Total() int { return total }

// TokenOf returns the ID of the Settler of an account, or an empty ID if it has none.
func TokenOf(addr address) grc721.TokenID {
	v := claimed.Get(addr.String())
	if v == nil {
		return ""
	}
	return v.(grc721.TokenID)
}

// TraitsOf returns the traits of a Settler.
func TraitsOf(tid grc721.TokenID) (nft.Traits, error) {
	packed, ok := traitsOf(tid)
	if !ok {
		return nft.Traits{}, grc721.ErrInvalidTokenId
	}
	return nft.Unpack(packed), nil
}

// traitsOf returns the packed traits of a Settler, or false if the ID is not a minted Settler.
func traitsOf(tid grc721.TokenID) (uint32, bool) {
	settlerID, ok := parseTokenID(tid)
	if !ok {
		return 0, false
	}

	v := tokens.Get(makeKey(settlerID))
	if v == nil {
		return 0, false
	}
	return v.(uint32), true
}

// tokenID returns the GRC721 ID of a Settler number.
func tokenID(settlerID int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(settlerID))
}

// parseTokenID returns the Settler number of an ID, only for the canonical form ("1", not "01" or "+1").
func parseTokenID(tid grc721.TokenID) (int, bool) {
	settlerID, err := strconv.Atoi(string(tid))
	if err != nil || settlerID < 1 || strconv.Itoa(settlerID) != string(tid) {
		return 0, false
	}
	return settlerID, true
}

func newTraitsFilter() *bloom.Bloom {
	m := uint64(28756) // bits
	k := uint64(7)     // hashes
	return bloom.NewWithMK(m, k)
}

func generateSeed(caller address, settlerID, nonce int) string {
	return hashSeed(seedPrefix(caller, settlerID), nonce)
}

func seedPrefix(caller address, settlerID int) string {
	return strconv.FormatInt(time.Now().UnixNano(), 10) + ":" + caller.String() +
		":" + strconv.Itoa(settlerID) + ":"
}

func hashSeed(prefix string, nonce int) string {
	sum := sha256.Sum256([]byte(prefix + strconv.Itoa(nonce)))
	return hex.EncodeToString(sum[:])
}

func splitProof(proof string) (int, []byte, string) {
	dot := strings.Index(proof, ".")
	if dot < 1 {
		return 0, nil, "the proof must be <index>.<aunts>"
	}

	index, err := strconv.Atoi(proof[:dot])
	if err != nil || index < 0 || index >= total {
		return 0, nil, "the index of the proof is not valid"
	}

	aunts, err := hex.DecodeString(proof[dot+1:])
	if err != nil || len(aunts)%32 != 0 || len(aunts) > 32*maxAunts {
		return 0, nil, "the aunts of the proof must be hashes of 32 bytes in hex"
	}
	return index, aunts, ""
}

func makeKey(settlerID int) string {
	s := strconv.Itoa(settlerID)
	return strings.Repeat("0", 5-len(s)) + s
}

func assertIsCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("unauthorized")
	}
}

func assertIsValidAlertType(t mdalert.Type) {
	switch t {
	case mdalert.TypeCaution, mdalert.TypeInfo, mdalert.TypeNote,
		mdalert.TypeSuccess, mdalert.TypeTip, mdalert.TypeWarning:
		return
	}
	panic("invalid notice type")
}

package nft

import (
	"strconv"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/mdtable/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mdalert/v0"
	"gno.land/p/nt/mux/v0"
)

const (
	// Gallery width is the width/height of gallery Settler images.
	galleryWidth = 96

	// Detail width is the width/height of Settler the image for detail views.
	detailWidth = 256

	// Gallery length is the number of last minted Settlers of the home page.
	galleryLen = 5
)

// Render renders the realm.
//
// By default renders the state of the mint and the last minted Settlers.
//
// Paths:
//   - `token/{id}`: A Settler with its traits and its owner.
//   - `addr/{address}`: The Settler of an account.
func Render(path string) string {
	router := mux.NewRouter()
	router.NotFoundHandler = func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write("Path not found")
	}

	router.HandleFunc("", renderHome)
	router.HandleFunc("token/{id}", renderToken)
	router.HandleFunc("addr/{addr}", renderAddr)

	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(md.H1("Settlers"))

	if Notice != "" {
		res.Write(mdalert.New(NoticeType, "Message", Notice, false).String() + "\n\n")
	}

	res.Write(md.Paragraph(
		"Soulbound pixel-art gnomes for the early settlers of Gno.land. " +
			"Every account that had at least 15 GNOT at the launch of `gnoland-1` can mint one, " +
			"first come first served. A Settler can't be transferred, it's soulbound",
	))

	res.Write(md.Paragraph("Realm paths:"))
	pathsTable := mdtable.Table{Headers: []string{"Path", "Description"}}
	pathsTable.Append([]string{
		md.InlineCode("token/{id}"),
		"A Settler with its traits and its owner.",
	})
	pathsTable.Append([]string{
		md.InlineCode("addr/{address}"),
		"The Settler of an account.",
	})
	res.Write(pathsTable.String() + "\n")

	minted := tokens.Size()
	if len(root) == 0 {
		res.Write(md.Paragraph("The mint is not open yet."))
	} else {
		res.Write(md.Paragraph(
			md.BulletItem(md.Bold("Minted:")+" "+strconv.Itoa(minted)+" of "+strconv.Itoa(supplyCap)) +
				md.BulletItem(md.Bold("Eligible accounts:")+" "+strconv.Itoa(total)) +
				md.BulletItem(md.Bold("Merkle root:")+" "+md.InlineCode(MerkleRoot())),
		))

		res.Write(md.Paragraph(
			"To mint, get your proof from the list of eligible accounts and call " +
				md.Link("Mint", RealmPath+"$help&func=Mint") + " with it; the account that " +
				"signs the transaction is the one that gets the Settler.",
		))
		res.Write(md.Paragraph(
			"Check the " + md.Link("README", RealmPath+"$source&file=README.md") + " for the full instructions.",
		))
	}

	if minted > 0 {
		res.Write(md.H2("Last Settlers"))
		tokens.ReverseIterateByOffset(0, galleryLen, func(key string, value any) bool {
			settlerID, _ := strconv.Atoi(key)
			img := image(settlerID, nft.Unpack(value.(uint32)), galleryWidth)
			res.Write("[" + img + "](" + tokenPath(settlerID) + ") ")
			return false
		})
		res.Write("\n\n")
	}

	res.Write(footer())
}

func renderToken(res *mux.ResponseWriter, req *mux.Request) {
	tid := grc721.TokenID(req.GetVar("id"))
	settlerID, _ := parseTokenID(tid)
	packed, ok := traitsOf(tid)
	if !ok {
		res.Write(md.Paragraph("Settler not found."))
		res.Write(md.Paragraph(backHomeLink()))
		return
	}

	res.Write(md.H1(settlerName(settlerID)))
	t := nft.Unpack(packed)
	res.Write(image(settlerID, t, detailWidth) + "\n\n")

	ownerAddr, _ := OwnerOf(tid)
	owner := ownerAddr.String()
	res.Write(md.Paragraph(
		"Owner: " + md.Link(owner, RealmPath+":addr/"+owner) +
			" · soulbound, it can't be transferred",
	))

	res.Write("| Trait | Value |\n| --- | --- |\n")
	for _, attr := range t.Attributes() {
		res.Write("| " + attr.Type + " | " + attr.Value + " |\n")
	}
	res.Write("\n")

	res.Write(md.Paragraph(backHomeLink()))
	res.Write(footer())
}

func renderAddr(res *mux.ResponseWriter, req *mux.Request) {
	addr := sanitize.BechString(req.GetVar("addr"), "g")
	if addr == "" {
		res.Write(md.Paragraph("Not a valid address."))
		res.Write(md.Paragraph(backHomeLink()))
		return
	}

	tid := TokenOf(address(addr))
	if tid == "" {
		res.Write(md.H1("Settler of " + md.InlineCode(addr)))
		res.Write(md.Paragraph("This account has not minted a Settler."))
		res.Write(md.Paragraph(backHomeLink()))
		return
	}

	settlerID, _ := parseTokenID(tid)
	packed, _ := traitsOf(tid)
	img := image(settlerID, nft.Unpack(packed), detailWidth)
	res.Write(md.H1("Settler of " + md.InlineCode(addr)))
	res.Write("[" + img + "](" + tokenPath(settlerID) + ")\n\n")
	res.Write(md.Paragraph(backHomeLink()))
	res.Write(footer())
}

func image(settlerID int, t nft.Traits, width int) string {
	alt := settlerName(settlerID)
	return "![" + alt + "](" + nft.RenderDataURI(t, nft.Options{Size: width}) + ")"
}

func tokenPath(settlerID int) string {
	return RealmPath + ":token/" + strconv.Itoa(settlerID)
}

func backHomeLink() string {
	return md.Link("< Home", RealmPath)
}

func settlerName(settlerID int) string {
	return "Settler #" + strconv.Itoa(settlerID)
}

func footer() string {
	return md.Blockquote(nft.Credits)
}

package avatar

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/mdalert/v0"
	"gno.land/p/nt/ownable/v0"
	settlers "gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft"
)

const (
	// MinSize is the minimum size allowed for an avatar in pixels.
	MinSize = 32

	// MaxSize is the maximum size allowed for an avatar in pixels.
	MaxSize = 2048
)

var (
	// Notice is a realm-wide message the admin can post at any time, shown at the top of the page.
	// It never affects SVG, URI or Markdown, it is purely informational.
	Notice string

	// NoticeType is the style Notice is shown as.
	NoticeType mdalert.Type

	// Realm path is the path of this realm.
	RealmPath string

	// Admin account for the realm, only valid to post or clear realm-wide notices.
	admin *ownable.Ownable

	// Go snippet is the Go usage example.
	goSnippet string

	// Gnokey snippet is the gnokey example.
	gnokeySnippet string
)

func init(cur realm) {
	RealmPath = strings.TrimPrefix(cur.PkgPath(), runtime.ChainDomain())
	admin = ownable.NewWithAddress(cur.Previous().Address())
	pkgPath := runtime.ChainDomain() + RealmPath

	goSnippet = "import \"" + pkgPath + "\"\n\n" +
		"func RenderUser(addr address) string {\n\treturn avatar.Markdown(addr, 32, true) " +
		"+ \" \" + addr.String()\n}\n"

	gnokeySnippet = "gnokey query vm/qrender \\\n" +
		"  -remote <remote> \\\n" +
		"  -data \"" + pkgPath + ":svg/{address}?size=256\" \\\n" +
		"  | tail -n +2 | sed '1s/^data: //' > settler.svg\n"
}

// Admin returns the address of the admin account.
func Admin() address { return admin.Owner() }

// TransferAdmin makes another account the admin. Only the admin can call it.
func TransferAdmin(cur realm, newAdmin address) {
	assertIsCurrent(cur)
	if err := admin.TransferOwnership(0, cur, newAdmin); err != nil {
		panic(err)
	}
}

// SetNotice posts a realm-wide message, shown at the top of the page.
func SetNotice(cur realm, alertType mdalert.Type, msg string) {
	assertIsCurrent(cur)
	admin.AssertOwnedBy(cur.Previous().Address())
	assertIsValidAlertType(alertType)

	NoticeType = alertType
	Notice = msg
	chain.Emit("NoticeSet", "type", string(alertType))
}

// ClearNotice removes the current notice.
func ClearNotice(cur realm) {
	assertIsCurrent(cur)
	admin.AssertOwnedBy(cur.Previous().Address())

	NoticeType = ""
	Notice = ""
	chain.Emit("NoticeCleared")
}

// SVG returns the SVG document of the Settler of an address, or an empty text if it has none.
//
// The size is the width and height in pixels of the square image, from 32 to 2048 (multiples of 32 keep
// every art pixel as a whole number of screen pixels). A size of 0 or less leaves out the width and the
// height, so that the image scales to its container. If transparent is true, the image has no background.
func SVG(addr address, size int, transparent bool) string {
	if tid, traits := lookup(addr); tid != "" {
		return nft.RenderSVG(traits, options(size, transparent))
	}
	return ""
}

// URI returns the image of the Settler of an address as a "data:image/svg+xml;charset=utf-8," URI, that can
// be used as the source of an image or as the address of a Markdown image, or an empty text if it has none.
// The size and transparent are the same as in SVG.
func URI(addr address, size int, transparent bool) string {
	if tid, traits := lookup(addr); tid != "" {
		return nft.RenderDataURI(traits, options(size, transparent))
	}
	return ""
}

// Markdown returns the avatar of an address as a Markdown image, or an empty text if it has none:
//
//	![Settler #12](data:image/svg+xml;charset=utf-8,...)
//
// The size and transparent are the same as in SVG.
func Markdown(addr address, size int, transparent bool) string {
	if tid, traits := lookup(addr); tid != "" {
		uri := nft.RenderDataURI(traits, options(size, transparent))
		return "![Settler #" + string(tid) + "](" + uri + ")"
	}
	return ""
}

// lookup returns the ID and traits of the Settler of an address, or an empty ID and a zero-value Traits if it
// has none.
func lookup(addr address) (grc721.TokenID, nft.Traits) {
	tid := settlers.TokenOf(addr)
	if tid == "" {
		return "", nft.Traits{}
	}

	traits, err := settlers.TraitsOf(tid)
	if err != nil {
		return "", nft.Traits{}
	}
	return tid, traits
}

// options builds the nft.Options for an image; size is clamped between MinSize and MaxSize (0 or less is
// left as 0, so the image has no fixed size and scales to its container), and transparent controls whether
// the background is drawn.
func options(size int, transparent bool) nft.Options {
	switch {
	case size <= 0:
		size = 0
	case size < MinSize:
		size = MinSize
	case size > MaxSize:
		size = MaxSize
	}

	return nft.Options{
		Size:         size,
		NoBackground: transparent,
	}
}

func assertIsCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("unauthorized")
	}
}

func assertIsValidAlertType(t mdalert.Type) {
	switch t {
	case mdalert.TypeCaution, mdalert.TypeInfo, mdalert.TypeNote,
		mdalert.TypeSuccess, mdalert.TypeTip, mdalert.TypeWarning:
		return
	}
	panic("invalid notice type")
}

package avatar

import (
	"strconv"

	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/mdtable/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/mdalert/v0"
	"gno.land/p/nt/mux/v0"
	settlers "gno.land/r/g17khqpukees4237dtn3astzapmp462vjhsz6st4/settlers/nft"
)

const (
	// Sample size is the size in pixels of the avatars in the pages.
	sampleSize = 48

	// Samples is how many avatars the home page shows.
	samples = 6
)

// Render renders the realm.
//
// By default renders what this realm is, how to use it, and some avatars.
//
// Paths:
//   - `svg/{address}`: The SVG of the Settler of an address.
//   - `md/{address}`: The Markdown that Markdown returns for an address, rendered, with the same parameters.
func Render(path string) string {
	router := mux.NewRouter()
	router.NotFoundHandler = func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write("Path not found")
	}

	router.HandleFunc("", renderHome)
	router.HandleFunc("svg/{addr}", renderSVG)
	router.HandleFunc("md/{addr}", renderMarkdown)

	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(md.H1("Settler avatars"))

	if Notice != "" {
		res.Write(mdalert.New(NoticeType, "Message", Notice, false).String() + "\n\n")
	}

	res.Write(md.Paragraph("This realm draws a Settler as a picture give an address."))
	res.Write(md.Paragraph(
		"It doesn't own the Settler, or store anything about it, it just looks one up and draws it, " +
			"fresh, every time it's asked. That's on purpose, keeping the drawing separate from the main " +
			"collection means any other realm or web app on Gno.land, a forum, a leaderboard, a profile " +
			"page, can show a Settler next to an address without needing to understand pixel art, traits, " +
			"or how any of it's put together.",
	))

	res.Write(md.Paragraph(
		"The " + md.Link("Settlers nft", settlers.RealmPath) + " realm is still the one that actually mints " +
			"the Settlers and keeps track of who owns what.",
	))

	res.Write(md.Paragraph("Realm paths:"))
	pathsTable := mdtable.Table{Headers: []string{"Path", "Description"}}
	pathsTable.Append([]string{
		md.InlineCode("svg/{address}"),
		"The SVG of the Settler of an address.",
	})
	pathsTable.Append([]string{
		md.InlineCode("md/{address}"),
		"The Markdown that Markdown returns for an address, rendered, with the same parameters.",
	})
	res.Write(pathsTable.String() + "\n")

	res.Write(md.H2("From a realm"))
	res.Write(md.Paragraph(
		"Call it directly from another realm, for example to show a Settler " +
			"next to an address in your own " + md.InlineCode("Render") + " function:",
	))
	res.Write(md.LanguageCodeBlock("go", goSnippet))

	table := mdtable.Table{Headers: []string{"Function", "Description"}}
	table.Append([]string{
		"Markdown(addr, size, transparent)",
		"The image, or an empty text if there is none",
	})
	table.Append([]string{
		"SVG(addr, size, transparent)",
		"The SVG document, or an empty text if there is none",
	})
	table.Append([]string{
		"URI(addr, size, transparent)",
		"The same image as a data URI",
	})
	res.Write(table.String() + "\n")

	res.Write(md.Paragraph(
		"The size is in pixels, from 32 to 2048, and 0 leaves it to the container. " +
			"With transparent the image has no background. Every call draws the image again and " +
			"costs gas (about 6 to 8 million), so use it in `Render` and not in a transaction.",
	))

	res.Write(md.H2("From a web app"))
	res.Write(md.Paragraph(
		"Ask the node for the page of an address, with `vm/qrender`, and use what it returns as an image: " +
			md.InlineCode(RealmPath+":svg/{address}?size=64&transparent=1") +
			". It is empty if the address has no Settler.",
	))
	res.Write(md.Paragraph("With gnokey, from a terminal, save it straight to a file:"))
	res.Write(md.LanguageCodeBlock("sh", gnokeySnippet))

	if n := settlers.TotalSupply(); n > 0 {
		res.Write(md.H2("Last Settlers"))

		for id := n; id > 0 && id > n-samples; id-- {
			tid := grc721.TokenID(strconv.FormatInt(id, 10))
			owner, err := settlers.OwnerOf(tid)
			if err != nil {
				continue
			}

			tokenPath := settlers.RealmPath + ":token/" + string(tid)
			table := mdtable.Table{Headers: []string{"", ""}}
			table.Append([]string{
				Markdown(owner, sampleSize, false),
				md.Link(owner.String(), tokenPath),
			})
			res.Write(table.String() + "\n")
		}
	}
}

func renderSVG(res *mux.ResponseWriter, req *mux.Request) {
	svg := SVG(address(req.GetVar("addr")), sizeParam(req), transparentParam(req))
	res.Write(svg)
}

func renderMarkdown(res *mux.ResponseWriter, req *mux.Request) {
	size := sizeParam(req)
	if size == 0 {
		size = sampleSize
	}

	addr := req.GetVar("addr")
	if !address(addr).IsValid() {
		res.Write(md.Paragraph("Not a valid address."))
		res.Write(md.Paragraph(md.Link("< Home", RealmPath)))
		return
	}

	res.Write(md.H1("Avatar of " + md.InlineCode(addr)))
	res.Write(md.Paragraph(Markdown(address(addr), size, transparentParam(req))))
	res.Write(md.Paragraph(md.Link("< Home", RealmPath)))
}

func sizeParam(req *mux.Request) int {
	size, err := strconv.Atoi(req.Query.Get("size"))
	if err != nil {
		return 0
	}
	return size
}

func transparentParam(req *mux.Request) bool {
	v := req.Query.Get("transparent")
	return v == "1" || v == "true"
}

// Package coinio is the chain-facing coin plumbing that every
// value-holding realm on gno.land repeats: verified payment receipt,
// disciplined payout, and reserve-protected surplus sweeping. It was
// extracted from two audited, pearl-1-validated realms (vault and
// bounties) whose implementations of these mechanics were
// line-identical.
//
// The package is PURE and STATELESS: it holds no balances, no roles,
// and no configuration; all state stays in the consuming realm (and
// its accounting package, e.g. feeledger). It emits no events —
// consumers emit their own. Every function either succeeds or panics,
// aborting the transaction: these are payment guards, and no failure
// here has a meaningful recovery path.
//
// CAPABILITY CONTRACT: pure packages cannot declare crossing
// functions (a first `realm` parameter), so every coin-moving function
// here uses the canonical secondary-parameter shape `(_ int, rlm
// realm, ...)` — the same pattern as chain treasury packages. Pass 0
// and your crossing entrypoint's own live `cur` (forwarded through
// non-crossing calls keeps it current). Each function asserts
// rlm.IsCurrent() before acting, so a stale, stored, or Previous()
// realm value fails closed (the designation-forgery guard secondary
// realm parameters require). Coins can only move FROM rlm.Address() —
// the calling realm itself — so no consumer can spend another realm's
// funds through this package.
//
// AUTHORIZATION is the consumer's responsibility: coinio decides HOW
// coins move, never WHO may move them. Gate your entrypoints before
// calling in.
//
// ORDERING CONTRACT (the one invariant coinio cannot enforce): debit
// your own accounting BEFORE calling Payout or Sweep
// (checks-effects-interactions). A panic inside coinio aborts the
// whole transaction, reverting your debit with it — that is what makes
// the debit-first order safe.
package coinio

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// Receive verifies the canonical receipt-guaranteed payment shape and
// returns the payer and amount:
//
//   - the caller of the consuming realm's entrypoint is an EOA via
//     MsgCall (IsUserCall) — the only shape where the chain guarantees
//     the -send envelope landed at the realm address before the body
//     ran (realms and maketx-run are rejected);
//   - the envelope is exactly one coin of the given denom;
//   - the amount is positive.
//
// Receive is a READ of the transaction's send envelope, NOT a
// consumption: a stateless pure package cannot mark an envelope spent,
// so calling Receive N times in one transaction reports the same
// envelope N times. CALL IT AT MOST ONCE PER TRANSACTION and credit
// its result at most once — a consumer that credits per call mints
// unbacked liabilities from a single -send.
//
// Call it first (and once) in any payable crossing entrypoint:
//
//	func Deposit(cur realm) {
//		from, amount := coinio.Receive(0, cur, "ugnot")
//		// credit `from` with `amount` in your accounting
//	}
func Receive(_ int, rlm realm, denom string) (from address, amount int64) {
	if !rlm.IsCurrent() {
		panic("coinio: realm capability is not current")
	}
	if denom == "" {
		panic("coinio: empty denom")
	}
	if !rlm.Previous().IsUserCall() {
		panic("coinio: payment must be a direct EOA call with -send (realms and maketx-run are rejected)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("coinio: send exactly one coin type: " + denom)
	}
	if sent[0].Amount <= 0 {
		panic("coinio: amount must be positive")
	}
	return rlm.Previous().Address(), sent[0].Amount
}

// Payout sends amount of denom from the calling realm's own address to
// `to`. DEBIT YOUR ACCOUNTING FIRST — a panic here (or anywhere later
// in the transaction) reverts the debit together with the send.
func Payout(_ int, rlm realm, to address, denom string, amount int64) {
	if !rlm.IsCurrent() {
		panic("coinio: realm capability is not current")
	}
	var zero address
	if to == zero {
		panic("coinio: empty payout address")
	}
	if denom == "" {
		panic("coinio: empty denom")
	}
	if amount <= 0 {
		panic("coinio: amount must be positive")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{chain.NewCoin(denom, amount)})
}

// Sweep sends the surplus of a single denomination — everything the
// calling realm holds above `reserve` — to `to`, and returns the swept
// amount. Pass your total liabilities as the reserve for the denom
// your accounting tracks, and 0 for foreign denominations. Panics if
// there is no positive surplus, so reserved funds are untouchable by
// construction. One denomination per call keeps the operation gas-
// bounded regardless of how many junk denoms third parties force-send.
func Sweep(_ int, rlm realm, to address, denom string, reserve int64) int64 {
	if !rlm.IsCurrent() {
		panic("coinio: realm capability is not current")
	}
	var zero address
	if to == zero {
		panic("coinio: empty sweep address")
	}
	if denom == "" {
		panic("coinio: empty denom")
	}
	if reserve < 0 {
		panic("coinio: negative reserve")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	surplus := bk.GetCoin(rlm.Address(), denom) - reserve
	if surplus <= 0 {
		panic("coinio: no surplus to sweep for " + denom)
	}
	bk.SendCoins(rlm.Address(), to, chain.Coins{chain.NewCoin(denom, surplus)})
	return surplus
}

// HeldAt returns the amount of denom held at addr. Read-only; usable
// from views and Render without a realm capability.
func HeldAt(addr address, denom string) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

// Package feeledger is a pure accounting primitive for realms that hold
// coins on behalf of users and charge an explicit protocol fee on
// deposits. It tracks per-account balances, the sum of user liabilities,
// and a separately-accrued fee pot. It never touches coins itself: the
// importing realm moves coins and drives this ledger, keeping the two in
// lock-step so that
//
//	coins held by realm == UsersTotal() + FeesAccrued() + surplus
//
// where surplus is coins pushed to the realm outside the ledger's flow
// (always >= 0, and 0 if every coin movement goes through the ledger).
//
// Fee model:
//   - Fees are expressed in basis points (1 bps = 0.01%); BpsDenominator
//     is 10000, so bps == 10000 means the whole deposit is fee.
//   - fee = floor(amount * bps / 10000). Rounding always favors the
//     DEPOSITOR: any fractional fee is dropped, the account is credited
//     amount - fee. A small deposit may therefore pay zero fee.
//   - There is no minimum fee. The maximum fee is bounded by the
//     per-ledger cap set at construction (maxFeeBps <= 10000), so a fee
//     can never exceed its deposit.
//   - bps == 0 is a valid configuration: fee is exactly 0 and the full
//     amount is credited.
//
// All failures are returned as errors and leave the ledger COMPLETELY
// UNCHANGED; callers in realms typically wrap calls so an error panics
// and aborts the transaction. Must* wrappers are provided and are the
// only functions in this package that panic.
//
// The ledger is address-agnostic: accounts are non-empty strings. Realms
// normally use address.String().
package feeledger

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// BpsDenominator is the fee basis: fees are bps/BpsDenominator of the
// deposited amount.
const BpsDenominator = int64(10000)

// Errors returned by Ledger operations.
var (
	ErrEmptyAccount  = errors.New("feeledger: empty account key")
	ErrInvalidAmount = errors.New("feeledger: amount must be positive")
	ErrInvalidBps    = errors.New("feeledger: fee bps out of range")
	ErrInsufficient  = errors.New("feeledger: insufficient balance")
	ErrOverflow      = errors.New("feeledger: int64 overflow")
)

// Ledger tracks per-account balances, their sum (user liabilities), and
// separately-accrued protocol fees. The zero value is not usable;
// construct with New.
type Ledger struct {
	maxFeeBps   int64
	balances    *avl.Tree // account string -> int64 (always > 0)
	usersTotal  int64     // == sum of all balances
	feesAccrued int64     // fees charged but not yet withdrawn
}

// New returns an empty ledger that rejects deposit fees above maxFeeBps.
// maxFeeBps must be in [0, BpsDenominator].
func New(maxFeeBps int64) (*Ledger, error) {
	if maxFeeBps < 0 || maxFeeBps > BpsDenominator {
		return nil, ErrInvalidBps
	}
	return &Ledger{
		maxFeeBps: maxFeeBps,
		balances:  avl.NewTree(),
	}, nil
}

// MustNew is New but panics on error.
func MustNew(maxFeeBps int64) *Ledger {
	l, err := New(maxFeeBps)
	if err != nil {
		panic(err)
	}
	return l
}

// MaxFeeBps returns the ledger's hard fee cap.
func (l *Ledger) MaxFeeBps() int64 {
	return l.maxFeeBps
}

// FeeFor returns the fee charged on amount at bps, using the ledger's
// rounding rule: floor(amount * bps / BpsDenominator). It is a pure
// preview — no state is read or written beyond validation against
// BpsDenominator (NOT the ledger cap; use it to inspect any policy).
// amount must be >= 0 and bps in [0, BpsDenominator].
func FeeFor(amount, bps int64) (int64, error) {
	if amount < 0 {
		return 0, ErrInvalidAmount
	}
	if bps < 0 || bps > BpsDenominator {
		return 0, ErrInvalidBps
	}
	return feeFor(amount, bps), nil
}

// feeFor computes floor(amount*bps/BpsDenominator) without intermediate
// overflow: amount = q*BpsDenominator + r, so the fee is
// q*bps + floor(r*bps/BpsDenominator). q*bps <= amount because
// bps <= BpsDenominator, and r*bps < BpsDenominator^2 (10^8), so every
// intermediate fits comfortably in int64. Inputs must be pre-validated.
func feeFor(amount, bps int64) int64 {
	q := amount / BpsDenominator
	r := amount % BpsDenominator
	return q*bps + r*bps/BpsDenominator
}

// Deposit credits account with amount minus the fee at feeBps, accruing
// the fee to the fee pot. Returns the credited amount and the fee
// (credited + fee == amount always). Fails with ErrEmptyAccount,
// ErrInvalidAmount (amount <= 0), ErrInvalidBps (feeBps outside
// [0, MaxFeeBps]), or ErrOverflow if the account balance or total
// liabilities would leave int64 range. On error nothing is modified.
func (l *Ledger) Deposit(account string, amount, feeBps int64) (credited, fee int64, err error) {
	if account == "" {
		return 0, 0, ErrEmptyAccount
	}
	if amount <= 0 {
		return 0, 0, ErrInvalidAmount
	}
	if feeBps < 0 || feeBps > l.maxFeeBps {
		return 0, 0, ErrInvalidBps
	}

	fee = feeFor(amount, feeBps)
	credited = amount - fee // >= 0; > 0 whenever feeBps < BpsDenominator

	newBalance, ok := checkedAdd(l.BalanceOf(account), credited)
	if !ok {
		return 0, 0, ErrOverflow
	}
	newUsersTotal, ok := checkedAdd(l.usersTotal, credited)
	if !ok {
		return 0, 0, ErrOverflow
	}
	newFeesAccrued, ok := checkedAdd(l.feesAccrued, fee)
	if !ok {
		return 0, 0, ErrOverflow
	}
	// Total liabilities must stay representable as one int64, since they
	// mirror a single coin balance held by the importing realm.
	if _, ok := checkedAdd(newUsersTotal, newFeesAccrued); !ok {
		return 0, 0, ErrOverflow
	}

	if newBalance > 0 {
		l.balances.Set(account, newBalance)
	}
	l.usersTotal = newUsersTotal
	l.feesAccrued = newFeesAccrued
	return credited, fee, nil
}

// MustDeposit is Deposit but panics on error.
func (l *Ledger) MustDeposit(account string, amount, feeBps int64) (credited, fee int64) {
	credited, fee, err := l.Deposit(account, amount, feeBps)
	if err != nil {
		panic(err)
	}
	return credited, fee
}

// Withdraw debits amount from account. Fails with ErrEmptyAccount,
// ErrInvalidAmount (amount <= 0), or ErrInsufficient if the balance is
// smaller than amount. A balance drained to zero is removed from
// storage. On error nothing is modified.
func (l *Ledger) Withdraw(account string, amount int64) error {
	if account == "" {
		return ErrEmptyAccount
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	balance := l.BalanceOf(account)
	if balance < amount {
		return ErrInsufficient
	}
	if balance == amount {
		l.balances.Remove(account)
	} else {
		l.balances.Set(account, balance-amount)
	}
	// usersTotal >= balance >= amount by the sum invariant, so this
	// cannot underflow.
	l.usersTotal -= amount
	return nil
}

// MustWithdraw is Withdraw but panics on error.
func (l *Ledger) MustWithdraw(account string, amount int64) {
	if err := l.Withdraw(account, amount); err != nil {
		panic(err)
	}
}

// WithdrawAll drains account's entire balance and returns it. Returns
// (0, nil) if the account holds nothing. Fails only with
// ErrEmptyAccount.
func (l *Ledger) WithdrawAll(account string) (int64, error) {
	if account == "" {
		return 0, ErrEmptyAccount
	}
	balance := l.BalanceOf(account)
	if balance == 0 {
		return 0, nil
	}
	l.balances.Remove(account)
	l.usersTotal -= balance
	return balance, nil
}

// WithdrawFees drains the accrued fee pot and returns the amount
// (0 if nothing has accrued). Never fails.
func (l *Ledger) WithdrawFees() int64 {
	fees := l.feesAccrued
	l.feesAccrued = 0
	return fees
}

// BalanceOf returns account's balance, or 0 if absent.
func (l *Ledger) BalanceOf(account string) int64 {
	v := l.balances.Get(account)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// UsersTotal returns the sum of all account balances (user liabilities).
func (l *Ledger) UsersTotal() int64 {
	return l.usersTotal
}

// FeesAccrued returns the fee pot: charged but not yet withdrawn.
func (l *Ledger) FeesAccrued() int64 {
	return l.feesAccrued
}

// Liabilities returns UsersTotal() + FeesAccrued() — everything the
// importing realm owes. Deposit guarantees this sum fits in int64.
func (l *Ledger) Liabilities() int64 {
	return l.usersTotal + l.feesAccrued
}

// Accounts returns the number of accounts with a non-zero balance.
func (l *Ledger) Accounts() int {
	return l.balances.Size()
}

// Iterate calls fn for each account in sorted order with its balance.
// Iteration stops early when fn returns true.
func (l *Ledger) Iterate(fn func(account string, balance int64) bool) {
	l.balances.Iterate("", "", func(key string, value any) bool {
		return fn(key, value.(int64))
	})
}

// checkedAdd returns a+b and reports whether the addition did not
// overflow int64.
func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

package feeledger

import "testing"

const (
	maxInt64 = int64(1<<63 - 1)
	minInt64 = int64(-1 << 63)
)

// mustPanicWith asserts fn panics with an error whose message is want.
// Non-crossing panics in the same package are recoverable.
func mustPanicWith(t *testing.T, want string, fn func()) {
	t.Helper()
	defer func() {
		r := recover()
		if r == nil {
			t.Fatalf("expected panic %q, got none", want)
		}
		err, ok := r.(error)
		if !ok || err.Error() != want {
			t.Fatalf("panic = %v, want %q", r, want)
		}
	}()
	fn()
}

func TestNewBounds(t *testing.T) {
	for _, bad := range []int64{-1, BpsDenominator + 1, minInt64, maxInt64} {
		if _, err := New(bad); err != ErrInvalidBps {
			t.Fatalf("New(%d) err = %v, want ErrInvalidBps", bad, err)
		}
	}
	for _, ok := range []int64{0, 1, BpsDenominator} {
		if _, err := New(ok); err != nil {
			t.Fatalf("New(%d) err = %v", ok, err)
		}
	}
	mustPanicWith(t, ErrInvalidBps.Error(), func() { MustNew(-1) })
}

func TestFeeForRounding(t *testing.T) {
	// floor(max * 0.9999) computed the same overflow-free way feeFor does.
	wantMaxAt9999 := maxInt64/10000*9999 + maxInt64%10000*9999/10000
	cases := []struct {
		amount, bps, want int64
	}{
		{999, 100, 9},      // 9.99 floors to 9
		{10000, 1, 1},      // exact
		{9999, 1, 0},       // 0.9999 floors to 0 — no minimum fee
		{1, 9999, 0},       // 0.9999 floors to 0
		{10, 9999, 9},      // 9.999 floors to 9
		{100, 10000, 100},  // full-fee bps: fee == amount
		{0, 500, 0},        // zero amount previews zero fee
		{1000, 0, 0},       // zero-fee config
		{1000, 250, 25},    // exact 2.5%
		{999, 250, 24},     // 24.975 floors to 24
		{maxInt64, 10000, maxInt64}, // no intermediate overflow
		{maxInt64, 9999, wantMaxAt9999},
	}
	for _, c := range cases {
		got, err := FeeFor(c.amount, c.bps)
		if err != nil {
			t.Fatalf("FeeFor(%d,%d) err = %v", c.amount, c.bps, err)
		}
		if got != c.want {
			t.Fatalf("FeeFor(%d,%d) = %d, want %d", c.amount, c.bps, got, c.want)
		}
		if got < 0 || got > c.amount {
			t.Fatalf("FeeFor(%d,%d) = %d out of [0,amount]", c.amount, c.bps, got)
		}
	}
	if _, err := FeeFor(-1, 100); err != ErrInvalidAmount {
		t.Fatalf("FeeFor(-1,100) err = %v, want ErrInvalidAmount", err)
	}
	if _, err := FeeFor(100, -1); err != ErrInvalidBps {
		t.Fatalf("FeeFor(100,-1) err = %v, want ErrInvalidBps", err)
	}
	if _, err := FeeFor(100, BpsDenominator+1); err != ErrInvalidBps {
		t.Fatalf("FeeFor over-bps err = %v, want ErrInvalidBps", err)
	}
}

func TestDepositValidation(t *testing.T) {
	l := MustNew(500)
	type bad struct {
		account     string
		amount, bps int64
		want        error
	}
	for _, c := range []bad{
		{"", 100, 0, ErrEmptyAccount},
		{"alice", 0, 0, ErrInvalidAmount},
		{"alice", -7, 0, ErrInvalidAmount},
		{"alice", minInt64, 0, ErrInvalidAmount},
		{"alice", 100, -1, ErrInvalidBps},
		{"alice", 100, 501, ErrInvalidBps}, // above the ledger cap
	} {
		if _, _, err := l.Deposit(c.account, c.amount, c.bps); err != c.want {
			t.Fatalf("Deposit(%q,%d,%d) err = %v, want %v", c.account, c.amount, c.bps, err, c.want)
		}
	}
	if l.UsersTotal() != 0 || l.FeesAccrued() != 0 || l.Accounts() != 0 {
		t.Fatal("failed deposits mutated state")
	}
}

func TestDepositAndAccumulate(t *testing.T) {
	l := MustNew(1000)
	credited, fee, err := l.Deposit("alice", 1000, 250)
	if err != nil || credited != 975 || fee != 25 {
		t.Fatalf("Deposit = (%d,%d,%v), want (975,25,nil)", credited, fee, err)
	}
	credited, fee, err = l.Deposit("alice", 999, 250)
	if err != nil || credited != 975 || fee != 24 { // fee floors, credit rounds up
		t.Fatalf("Deposit#2 = (%d,%d,%v), want (975,24,nil)", credited, fee, err)
	}
	if got := l.BalanceOf("alice"); got != 1950 {
		t.Fatalf("BalanceOf = %d, want 1950", got)
	}
	if l.UsersTotal() != 1950 || l.FeesAccrued() != 49 || l.Liabilities() != 1999 {
		t.Fatalf("totals = %d/%d/%d", l.UsersTotal(), l.FeesAccrued(), l.Liabilities())
	}
	// credited + fee always reassembles both deposits exactly.
	if l.Liabilities() != 1000+999 {
		t.Fatal("conservation broken: credited+fee != deposited")
	}
}

func TestFullFeeBpsCreditsZero(t *testing.T) {
	l := MustNew(BpsDenominator)
	credited, fee, err := l.Deposit("alice", 777, BpsDenominator)
	if err != nil || credited != 0 || fee != 777 {
		t.Fatalf("Deposit = (%d,%d,%v), want (0,777,nil)", credited, fee, err)
	}
	if l.Accounts() != 0 || l.BalanceOf("alice") != 0 {
		t.Fatal("zero-credit deposit must not create an account entry")
	}
	if l.FeesAccrued() != 777 || l.UsersTotal() != 0 {
		t.Fatal("fee pot mismatch on full-fee deposit")
	}
}

func TestDepositOverflow(t *testing.T) {
	l := MustNew(BpsDenominator)
	if _, _, err := l.Deposit("alice", maxInt64, 0); err != nil {
		t.Fatalf("seed deposit err = %v", err)
	}
	// Account balance would overflow.
	if _, _, err := l.Deposit("alice", 1, 0); err != ErrOverflow {
		t.Fatalf("balance-overflow err = %v, want ErrOverflow", err)
	}
	// Joint liabilities (users + fees) would overflow even though the
	// fee pot alone would not.
	if _, _, err := l.Deposit("bob", 100, BpsDenominator); err != ErrOverflow {
		t.Fatalf("liabilities-overflow err = %v, want ErrOverflow", err)
	}
	if l.BalanceOf("bob") != 0 || l.FeesAccrued() != 0 || l.UsersTotal() != maxInt64 {
		t.Fatal("failed overflow deposits mutated state")
	}
}

func TestWithdraw(t *testing.T) {
	l := MustNew(0)
	l.MustDeposit("alice", 1000, 0)

	if err := l.Withdraw("", 10); err != ErrEmptyAccount {
		t.Fatalf("empty account err = %v", err)
	}
	if err := l.Withdraw("alice", 0); err != ErrInvalidAmount {
		t.Fatalf("zero amount err = %v", err)
	}
	if err := l.Withdraw("alice", -3); err != ErrInvalidAmount {
		t.Fatalf("negative amount err = %v", err)
	}
	if err := l.Withdraw("alice", 1001); err != ErrInsufficient {
		t.Fatalf("over-balance err = %v", err)
	}
	if err := l.Withdraw("ghost", 1); err != ErrInsufficient {
		t.Fatalf("absent account err = %v", err)
	}
	if l.BalanceOf("alice") != 1000 || l.UsersTotal() != 1000 {
		t.Fatal("failed withdrawals mutated state")
	}

	if err := l.Withdraw("alice", 400); err != nil {
		t.Fatalf("partial withdraw err = %v", err)
	}
	if l.BalanceOf("alice") != 600 || l.UsersTotal() != 600 || l.Accounts() != 1 {
		t.Fatal("partial withdraw wrong state")
	}
	if err := l.Withdraw("alice", 600); err != nil {
		t.Fatalf("exact withdraw err = %v", err)
	}
	if l.BalanceOf("alice") != 0 || l.UsersTotal() != 0 || l.Accounts() != 0 {
		t.Fatal("exact withdraw must remove the account entry")
	}
	if err := l.Withdraw("alice", 1); err != ErrInsufficient {
		t.Fatalf("repeat withdraw err = %v, want ErrInsufficient", err)
	}
	mustPanicWith(t, ErrInsufficient.Error(), func() { l.MustWithdraw("alice", 1) })
}

func TestWithdrawAll(t *testing.T) {
	l := MustNew(0)
	if got, err := l.WithdrawAll("nobody"); err != nil || got != 0 {
		t.Fatalf("WithdrawAll(nobody) = (%d,%v), want (0,nil)", got, err)
	}
	if _, err := l.WithdrawAll(""); err != ErrEmptyAccount {
		t.Fatalf("WithdrawAll(\"\") err = %v", err)
	}
	l.MustDeposit("alice", 555, 0)
	if got, err := l.WithdrawAll("alice"); err != nil || got != 555 {
		t.Fatalf("WithdrawAll = (%d,%v), want (555,nil)", got, err)
	}
	if got, err := l.WithdrawAll("alice"); err != nil || got != 0 {
		t.Fatalf("repeat WithdrawAll = (%d,%v), want (0,nil)", got, err)
	}
	if l.UsersTotal() != 0 || l.Accounts() != 0 {
		t.Fatal("WithdrawAll left state behind")
	}
}

func TestWithdrawFees(t *testing.T) {
	l := MustNew(1000)
	l.MustDeposit("alice", 10000, 1000) // fee 1000
	l.MustDeposit("bob", 10000, 1000)   // fee 1000
	if got := l.WithdrawFees(); got != 2000 {
		t.Fatalf("WithdrawFees = %d, want 2000", got)
	}
	if got := l.WithdrawFees(); got != 0 {
		t.Fatalf("repeat WithdrawFees = %d, want 0", got)
	}
	if l.FeesAccrued() != 0 || l.UsersTotal() != 18000 {
		t.Fatal("WithdrawFees corrupted totals")
	}
}

func TestConservationAcrossSequence(t *testing.T) {
	l := MustNew(1000)
	deposited := int64(0)
	withdrawn := int64(0)
	feesOut := int64(0)

	step := func() {
		t.Helper()
		// Internal consistency: usersTotal == sum of balances.
		sum := int64(0)
		l.Iterate(func(_ string, b int64) bool {
			if b <= 0 {
				t.Fatal("zero/negative balance stored")
			}
			sum += b
			return false
		})
		if sum != l.UsersTotal() {
			t.Fatalf("usersTotal %d != Σ balances %d", l.UsersTotal(), sum)
		}
		// Conservation: everything in == everything owed + everything out.
		if deposited != l.Liabilities()+withdrawn+feesOut {
			t.Fatalf("conservation: in=%d owed=%d out=%d+%d",
				deposited, l.Liabilities(), withdrawn, feesOut)
		}
	}

	deposit := func(who string, amt, bps int64) {
		l.MustDeposit(who, amt, bps)
		deposited += amt
		step()
	}
	claim := func(who string, amt int64) {
		l.MustWithdraw(who, amt)
		withdrawn += amt
		step()
	}

	deposit("alice", 1000, 0)
	deposit("bob", 999, 250)
	deposit("alice", 12345, 1000)
	claim("alice", 1000)
	deposit("carol", 1, 1000) // fee floors to 0
	feesOut += l.WithdrawFees()
	step()
	claim("bob", 974)
	all, _ := l.WithdrawAll("alice")
	withdrawn += all
	step()
	deposit("dave", 7, 999)
	feesOut += l.WithdrawFees()
	step()
}

func TestCheckedAddBranches(t *testing.T) {
	cases := []struct {
		a, b, want int64
		ok         bool
	}{
		{5, 3, 8, true},
		{5, -3, 2, true},   // negative-b branch, no overflow
		{-4, -6, -10, true},
		{maxInt64, 1, 0, false},  // positive overflow
		{minInt64, -1, 0, false}, // negative overflow
		{maxInt64, -maxInt64, 0, true},
	}
	for _, c := range cases {
		got, ok := checkedAdd(c.a, c.b)
		if ok != c.ok || (ok && got != c.want) {
			t.Fatalf("checkedAdd(%d,%d) = (%d,%v), want (%d,%v)", c.a, c.b, got, ok, c.want, c.ok)
		}
	}
}

func TestIterateSortedAndEarlyStop(t *testing.T) {
	l := MustNew(0)
	l.MustDeposit("carol", 3, 0)
	l.MustDeposit("alice", 1, 0)
	l.MustDeposit("bob", 2, 0)
	got := ""
	l.Iterate(func(a string, _ int64) bool {
		got += a + ","
		return false
	})
	if got != "alice,bob,carol," {
		t.Fatalf("Iterate order = %q", got)
	}
	n := 0
	l.Iterate(func(string, int64) bool { n++; return n == 2 })
	if n != 2 {
		t.Fatalf("early stop visited %d", n)
	}
}

// Package duebook is a pure scheduling primitive for realms that need to
// authorize an action now and perform it later. It is to *time* what
// feeledger is to *money*: it holds no coins, performs no effects, imports
// no chain APIs, and owns no package-level state. The importing realm owns
// a *Book, supplies the clock, and performs its own effects.
//
// # The one idea
//
// A realm does not ask duebook to execute anything — Gno has no autonomous
// execution, so "scheduled" always means "someone sends a transaction
// later". What a realm actually needs is for that later transaction to be
// authorized exactly once. Claim is that step:
//
//	d, err := book.Claim(id, now)
//	if err != nil {
//		panic(err) // not due, expired, cancelled, or already claimed
//	}
//	// ... the realm performs its own effect here, under its own authority
//
// Claim checks due / not-expired / still-open and CONSUMES the deferral in
// the same call, before returning. The realm then acts. Replay is not
// guarded against, it is structurally impossible:
//
//   - IDs are allocated monotonically from an internal counter and are
//     NEVER reused, for the lifetime of the Book;
//   - a successful Claim removes the deferral before returning;
//
// so at most one Claim per ID can ever succeed, across all transactions,
// forever. A second Claim of the same ID returns ErrNotFound whether the
// first one happened in this transaction or a year ago.
//
// Because the realm performs the effect itself, no closure, callback, or
// capability ever crosses a realm boundary. duebook cannot be handed code
// to run, so it cannot be tricked into running the wrong code.
//
// # Lifecycle
//
// A deferral is open from Schedule until exactly one of Claim, Cancel, or
// Expire consumes it. There is no other transition and no way back.
//
//	Schedule ──> open ──┬── Claim   (now >= DueAt, before ExpiresAt)
//	                    ├── Cancel  (owner only, any time while open)
//	                    └── Expire  (anyone, once now >= ExpiresAt)
//
// Claimability is the half-open interval [DueAt, ExpiresAt): due at DueAt,
// no longer claimable at ExpiresAt. A deferral scheduled with ttl == 0
// never expires and has ExpiresAt == 0.
//
// # State growth
//
// Consumed deferrals are removed, not archived — the ID counter, not a
// tombstone, is what prevents replay, so there is nothing to keep. Open
// deferrals are capped per Book at construction. Storage is therefore
// bounded by maxOpen regardless of how many deferrals have ever existed.
// Audit history belongs in the consuming realm's events.
//
// # Consumer contract (the parts the package cannot enforce)
//
//  1. SUPPLY A REAL CLOCK. duebook cannot verify that `now` came from
//     runtime.ChainHeight() or time.Now().Unix(). A realm that lets a caller
//     choose `now` has no delay at all. Pass the chain's clock, never a
//     transaction parameter. This is the single most important obligation
//     and the one most commonly got wrong.
//  2. USE ONE CLOCK CONSISTENTLY. Heights and seconds must not be mixed
//     within a Book; delay, ttl and now are all in the caller's chosen
//     unit.
//  3. DO NOT EXPORT THE BOOK. A *Book is a mutable handle. Returning one
//     across a realm boundary hands out the right to schedule, cancel and
//     claim. Expose your own crossing functions instead; this package
//     returns Deferral values, never pointers into its state.
//  4. AUTHORIZE THE ACTOR. duebook authenticates nothing but ownership on
//     Cancel. Who may Schedule, and who may Claim, are the realm's policy —
//     derive the caller from cur.Previous().Address(), not from an argument.
//  5. ACT AFTER A SUCCESSFUL CLAIM, IN THE SAME TRANSACTION. Claim's
//     return value is the authorization. Storing it to act on later
//     reintroduces the replay window this package exists to close.
//
// All failures are returned as errors and leave the Book COMPLETELY
// UNCHANGED. Must* wrappers are the only functions here that panic.
//
// The Book is address-agnostic: owners are non-empty strings. Realms
// normally use address.String().
package duebook

import (
	"errors"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// MaxPayloadLen bounds a single deferral's payload. The payload is opaque
// to duebook — it exists so a realm can recover what it scheduled without
// keeping a parallel table.
const MaxPayloadLen = 4096

// MaxOpenLimit is the largest maxOpen a Book may be constructed with. It
// bounds the worst-case cost of Due and IterateOpen, which scan the open
// set.
const MaxOpenLimit = 10000

// Errors returned by Book operations.
var (
	ErrEmptyOwner    = errors.New("duebook: empty owner key")
	ErrPayloadTooBig = errors.New("duebook: payload exceeds MaxPayloadLen")
	ErrInvalidNow    = errors.New("duebook: now must be non-negative")
	ErrInvalidDelay  = errors.New("duebook: delay outside [minDelay, maxDelay]")
	ErrInvalidTTL    = errors.New("duebook: ttl must be non-negative")
	ErrInvalidConfig = errors.New("duebook: invalid book configuration")
	ErrBookFull      = errors.New("duebook: open deferral cap reached")
	ErrNotFound      = errors.New("duebook: no such open deferral")
	ErrNotDue        = errors.New("duebook: not due yet")
	ErrExpired       = errors.New("duebook: deferral has expired")
	ErrNotExpired    = errors.New("duebook: deferral has not expired")
	ErrNotOwner      = errors.New("duebook: caller does not own this deferral")
	ErrOverflow      = errors.New("duebook: int64 overflow")
	ErrIDExhausted   = errors.New("duebook: identifier space exhausted")
)

// Deferral is a scheduled action. It is returned BY VALUE: holders cannot
// reach into a Book through it. Payload is opaque to this package.
//
// ExpiresAt == 0 means the deferral never expires. Otherwise the deferral
// is claimable exactly on [DueAt, ExpiresAt).
type Deferral struct {
	ID        uint64
	Owner     string
	Payload   string
	CreatedAt int64
	DueAt     int64
	ExpiresAt int64
}

// IsDue reports whether the deferral has reached its due time at now.
func (d Deferral) IsDue(now int64) bool { return now >= d.DueAt }

// IsExpired reports whether the deferral is past its expiry at now.
// A deferral with no expiry is never expired.
func (d Deferral) IsExpired(now int64) bool {
	return d.ExpiresAt != 0 && now >= d.ExpiresAt
}

// IsClaimable reports whether Claim would succeed at now, assuming the
// deferral is still open.
func (d Deferral) IsClaimable(now int64) bool {
	return d.IsDue(now) && !d.IsExpired(now)
}

// Book holds the open deferrals of one consuming realm. The zero value is
// not usable; construct with New.
type Book struct {
	minDelay int64
	maxDelay int64
	maxOpen  int
	nextID   uint64    // never decreases; IDs are never reused
	open     *avl.Tree // padded id -> Deferral
}

// New returns an empty Book.
//
// minDelay is the floor on how far ahead a deferral may be scheduled; 0
// permits same-instant scheduling. maxDelay is the ceiling, and doubles as
// the overflow guard on now+delay. maxOpen caps simultaneously open
// deferrals and must be in [1, MaxOpenLimit].
//
// Units are the caller's choice — block heights or seconds — but must be
// used consistently for the life of the Book.
func New(minDelay, maxDelay int64, maxOpen int) (*Book, error) {
	if minDelay < 0 || maxDelay < minDelay {
		return nil, ErrInvalidConfig
	}
	if maxOpen < 1 || maxOpen > MaxOpenLimit {
		return nil, ErrInvalidConfig
	}
	return &Book{
		minDelay: minDelay,
		maxDelay: maxDelay,
		maxOpen:  maxOpen,
		nextID:   1,
		open:     avl.NewTree(),
	}, nil
}

// MustNew is New but panics on error.
func MustNew(minDelay, maxDelay int64, maxOpen int) *Book {
	b, err := New(minDelay, maxDelay, maxOpen)
	if err != nil {
		panic(err)
	}
	return b
}

// MinDelay returns the Book's scheduling floor.
func (b *Book) MinDelay() int64 { return b.minDelay }

// MaxDelay returns the Book's scheduling ceiling.
func (b *Book) MaxDelay() int64 { return b.maxDelay }

// MaxOpen returns the Book's cap on simultaneously open deferrals.
func (b *Book) MaxOpen() int { return b.maxOpen }

// OpenCount returns how many deferrals are currently open.
func (b *Book) OpenCount() int { return b.open.Size() }

// NextID returns the identifier the next Schedule will allocate. It only
// ever increases, which is what makes a consumed ID unreusable.
func (b *Book) NextID() uint64 { return b.nextID }

// Schedule opens a deferral owned by owner, due at now+delay, expiring
// ttl after that (ttl == 0 means it never expires). It returns the new
// deferral's ID.
//
// Fails with ErrEmptyOwner, ErrPayloadTooBig, ErrInvalidNow (now < 0),
// ErrInvalidDelay (delay outside [MinDelay, MaxDelay]), ErrInvalidTTL
// (ttl < 0), ErrBookFull, ErrOverflow, or ErrIDExhausted. On error
// nothing is modified.
func (b *Book) Schedule(owner, payload string, now, delay, ttl int64) (uint64, error) {
	if owner == "" {
		return 0, ErrEmptyOwner
	}
	if len(payload) > MaxPayloadLen {
		return 0, ErrPayloadTooBig
	}
	if now < 0 {
		return 0, ErrInvalidNow
	}
	if delay < b.minDelay || delay > b.maxDelay {
		return 0, ErrInvalidDelay
	}
	if ttl < 0 {
		return 0, ErrInvalidTTL
	}
	if b.open.Size() >= b.maxOpen {
		return 0, ErrBookFull
	}
	if b.nextID == 0 {
		return 0, ErrIDExhausted
	}

	dueAt, ok := checkedAdd(now, delay)
	if !ok {
		return 0, ErrOverflow
	}
	expiresAt := int64(0)
	if ttl > 0 {
		expiresAt, ok = checkedAdd(dueAt, ttl)
		if !ok {
			return 0, ErrOverflow
		}
	}

	id := b.nextID
	b.nextID++
	b.open.Set(idKey(id), Deferral{
		ID:        id,
		Owner:     owner,
		Payload:   payload,
		CreatedAt: now,
		DueAt:     dueAt,
		ExpiresAt: expiresAt,
	})
	return id, nil
}

// MustSchedule is Schedule but panics on error.
func (b *Book) MustSchedule(owner, payload string, now, delay, ttl int64) uint64 {
	id, err := b.Schedule(owner, payload, now, delay, ttl)
	if err != nil {
		panic(err)
	}
	return id
}

// Claim consumes the deferral and returns it, authorizing the caller to
// perform the deferred action NOW, in this transaction.
//
// It succeeds only while the deferral is open and now is in
// [DueAt, ExpiresAt). The deferral is removed BEFORE Claim returns, so a
// re-entrant or later Claim of the same ID finds nothing; combined with
// non-reused IDs, at most one Claim per ID ever succeeds.
//
// Fails with ErrInvalidNow, ErrNotFound (never existed, or already
// consumed by Claim/Cancel/Expire), ErrNotDue, or ErrExpired. On error
// nothing is modified.
//
// duebook does NOT check who is claiming: whether a deferral is
// permissionlessly claimable or restricted to its owner is the consuming
// realm's policy, applied before calling Claim.
func (b *Book) Claim(id uint64, now int64) (Deferral, error) {
	if now < 0 {
		return Deferral{}, ErrInvalidNow
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if !d.IsDue(now) {
		return Deferral{}, ErrNotDue
	}
	if d.IsExpired(now) {
		return Deferral{}, ErrExpired
	}
	// Consume before returning: the caller acts only after this point, so
	// the deferral is already gone when the effect runs.
	b.open.Remove(idKey(id))
	return d, nil
}

// MustClaim is Claim but panics on error.
func (b *Book) MustClaim(id uint64, now int64) Deferral {
	d, err := b.Claim(id, now)
	if err != nil {
		panic(err)
	}
	return d
}

// Cancel consumes an open deferral without performing it. Only its owner
// may cancel, and cancellation is permitted at any time while the deferral
// is open — including after it became due but before anyone claimed it.
//
// Fails with ErrEmptyOwner, ErrNotFound, or ErrNotOwner. On error nothing
// is modified.
func (b *Book) Cancel(id uint64, owner string) (Deferral, error) {
	if owner == "" {
		return Deferral{}, ErrEmptyOwner
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if d.Owner != owner {
		return Deferral{}, ErrNotOwner
	}
	b.open.Remove(idKey(id))
	return d, nil
}

// MustCancel is Cancel but panics on error.
func (b *Book) MustCancel(id uint64, owner string) Deferral {
	d, err := b.Cancel(id, owner)
	if err != nil {
		panic(err)
	}
	return d
}

// Expire consumes a deferral that is past its expiry, reclaiming its
// storage. It is deliberately permissionless: an expired deferral can
// never be claimed again, so letting anyone clear it keeps a Book from
// silting up with dead entries that block Schedule against maxOpen.
//
// Fails with ErrInvalidNow, ErrNotFound, or ErrNotExpired (including for
// deferrals with no expiry, which never expire). On error nothing is
// modified.
func (b *Book) Expire(id uint64, now int64) (Deferral, error) {
	if now < 0 {
		return Deferral{}, ErrInvalidNow
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if !d.IsExpired(now) {
		return Deferral{}, ErrNotExpired
	}
	b.open.Remove(idKey(id))
	return d, nil
}

// MustExpire is Expire but panics on error.
func (b *Book) MustExpire(id uint64, now int64) Deferral {
	d, err := b.Expire(id, now)
	if err != nil {
		panic(err)
	}
	return d
}

// Get returns an open deferral by ID. The second result is false if the
// deferral never existed or has already been consumed — Get cannot tell
// those apart, by design: consumed deferrals leave no tombstone.
//
// Get is a read-only preview and never authorizes anything. Only Claim's
// return value authorizes an action.
func (b *Book) Get(id uint64) (Deferral, bool) { return b.get(id) }

// Due returns up to limit open deferrals that are claimable at now, in
// ascending ID order (oldest first). A limit <= 0 returns nothing.
//
// It scans the open set, so its cost is bounded by MaxOpen.
func (b *Book) Due(now int64, limit int) []Deferral {
	out := []Deferral{}
	if limit <= 0 || now < 0 {
		return out
	}
	b.open.Iterate("", "", func(_ string, value any) bool {
		d := value.(Deferral)
		if d.IsClaimable(now) {
			out = append(out, d)
		}
		return len(out) >= limit
	})
	return out
}

// Expirable returns up to limit open deferrals that Expire would accept at
// now, in ascending ID order. A limit <= 0 returns nothing.
func (b *Book) Expirable(now int64, limit int) []Deferral {
	out := []Deferral{}
	if limit <= 0 || now < 0 {
		return out
	}
	b.open.Iterate("", "", func(_ string, value any) bool {
		d := value.(Deferral)
		if d.IsExpired(now) {
			out = append(out, d)
		}
		return len(out) >= limit
	})
	return out
}

// IterateOpen calls fn for every open deferral in ascending ID order.
// Iteration stops early when fn returns true.
//
// fn receives a COPY: Deferral is passed by value and holds only scalars
// and strings, so fn gets no pointer into the Book and cannot reach past
// it — Book's fields are all unexported.
//
// Two rules for fn, and the second is the one that is easy to miss.
//
//   - Do not Schedule, Claim, Cancel or Expire from inside fn: mutating
//     the tree while iterating it is undefined. Collect IDs first, then
//     act after IterateOpen returns.
//
//   - fn runs under the CALLING REALM'S STORAGE AUTHORITY. This method's
//     receiver is stamped with the importing realm's PkgID, so the borrow
//     rules leave the realm context set to that realm for the whole
//     callback, and a top-level fn has no receiver and no declaring realm
//     to anchor it elsewhere. A callback that re-enters the calling
//     realm's own mutators therefore does so with that realm's authority.
//     Never pass a caller-supplied function here from inside a
//     permission-gated path; pass only a closure this package's consumer
//     wrote itself.
func (b *Book) IterateOpen(fn func(Deferral) bool) {
	b.open.Iterate("", "", func(_ string, value any) bool {
		return fn(value.(Deferral))
	})
}

// get looks up an open deferral without touching the tree otherwise.
func (b *Book) get(id uint64) (Deferral, bool) {
	v := b.open.Get(idKey(id))
	if v == nil {
		return Deferral{}, false
	}
	return v.(Deferral), true
}

// idKey encodes an ID so that avl's lexical key order matches numeric ID
// order. math.MaxUint64 is 20 digits, so a fixed 20-wide zero-padded
// decimal is both sufficient and unambiguous.
func idKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	const width = 20
	if len(s) >= width {
		return s
	}
	return zeros[:width-len(s)] + s
}

const zeros = "00000000000000000000"

// checkedAdd returns a+b and reports whether the addition did not
// overflow int64.
func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

package duebook

import "testing"

const (
	alice = "g1alice"
	bob   = "g1bob"
)

// newBook is the default fixture: delay in [10, 1000], 8 open slots.
func newBook(t *testing.T) *Book {
	t.Helper()
	b, err := New(10, 1000, 8)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	return b
}

// --- construction ---------------------------------------------------------

func TestNewRejectsBadConfig(t *testing.T) {
	cases := []struct {
		name                string
		min, max            int64
		maxOpen             int
	}{
		{"negative min", -1, 100, 4},
		{"max below min", 100, 99, 4},
		{"zero maxOpen", 0, 100, 0},
		{"negative maxOpen", 0, 100, -1},
		{"maxOpen over limit", 0, 100, MaxOpenLimit + 1},
	}
	for _, c := range cases {
		if _, err := New(c.min, c.max, c.maxOpen); err != ErrInvalidConfig {
			t.Errorf("%s: got %v, want ErrInvalidConfig", c.name, err)
		}
	}
}

func TestNewAcceptsZeroMinDelay(t *testing.T) {
	b, err := New(0, 0, 1)
	if err != nil {
		t.Fatalf("New(0,0,1): %v", err)
	}
	id, err := b.Schedule(alice, "", 100, 0, 0)
	if err != nil {
		t.Fatalf("Schedule: %v", err)
	}
	// min == max == 0 means due immediately.
	if _, err := b.Claim(id, 100); err != nil {
		t.Fatalf("Claim at due instant: %v", err)
	}
}

// --- scheduling -----------------------------------------------------------

func TestScheduleComputesWindow(t *testing.T) {
	b := newBook(t)
	id, err := b.Schedule(alice, "payload", 1000, 50, 200)
	if err != nil {
		t.Fatalf("Schedule: %v", err)
	}
	d, ok := b.Get(id)
	if !ok {
		t.Fatal("Get: not found")
	}
	if d.CreatedAt != 1000 || d.DueAt != 1050 || d.ExpiresAt != 1250 {
		t.Errorf("window = (%d,%d,%d), want (1000,1050,1250)", d.CreatedAt, d.DueAt, d.ExpiresAt)
	}
	if d.Owner != alice || d.Payload != "payload" {
		t.Errorf("owner/payload = %q/%q", d.Owner, d.Payload)
	}
}

func TestScheduleZeroTTLNeverExpires(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 0)
	d, _ := b.Get(id)
	if d.ExpiresAt != 0 {
		t.Fatalf("ExpiresAt = %d, want 0", d.ExpiresAt)
	}
	if d.IsExpired(1 << 62) {
		t.Error("ttl==0 deferral reported expired")
	}
	// Still claimable in the far future.
	if _, err := b.Claim(id, 1<<62); err != nil {
		t.Fatalf("Claim far future: %v", err)
	}
}

func TestScheduleValidation(t *testing.T) {
	b := newBook(t)
	big := make([]byte, MaxPayloadLen+1)
	cases := []struct {
		name    string
		owner   string
		payload string
		now     int64
		delay   int64
		ttl     int64
		want    error
	}{
		{"empty owner", "", "", 0, 10, 0, ErrEmptyOwner},
		{"payload too big", alice, string(big), 0, 10, 0, ErrPayloadTooBig},
		{"negative now", alice, "", -1, 10, 0, ErrInvalidNow},
		{"delay below min", alice, "", 0, 9, 0, ErrInvalidDelay},
		{"delay above max", alice, "", 0, 1001, 0, ErrInvalidDelay},
		{"negative delay", alice, "", 0, -5, 0, ErrInvalidDelay},
		{"negative ttl", alice, "", 0, 10, -1, ErrInvalidTTL},
	}
	for _, c := range cases {
		if _, err := b.Schedule(c.owner, c.payload, c.now, c.delay, c.ttl); err != c.want {
			t.Errorf("%s: got %v, want %v", c.name, err, c.want)
		}
	}
	if b.OpenCount() != 0 {
		t.Errorf("failed Schedules mutated the book: OpenCount = %d", b.OpenCount())
	}
	if b.NextID() != 1 {
		t.Errorf("failed Schedules consumed IDs: NextID = %d", b.NextID())
	}
}

func TestScheduleOverflowGuard(t *testing.T) {
	b, err := New(0, 1<<62, 4)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	const huge = int64(1<<63 - 1)
	// now + delay overflows.
	if _, err := b.Schedule(alice, "", huge-10, 1<<62, 0); err != ErrOverflow {
		t.Errorf("dueAt overflow: got %v, want ErrOverflow", err)
	}
	// dueAt + ttl overflows.
	if _, err := b.Schedule(alice, "", huge-1<<62, 1<<62, huge); err != ErrOverflow {
		t.Errorf("expiresAt overflow: got %v, want ErrOverflow", err)
	}
	if b.OpenCount() != 0 {
		t.Errorf("overflow left state behind: OpenCount = %d", b.OpenCount())
	}
}

func TestScheduleRespectsCap(t *testing.T) {
	b, _ := New(0, 100, 2)
	b.MustSchedule(alice, "", 0, 10, 0)
	b.MustSchedule(alice, "", 0, 10, 0)
	if _, err := b.Schedule(alice, "", 0, 10, 0); err != ErrBookFull {
		t.Fatalf("third Schedule: got %v, want ErrBookFull", err)
	}
	// Consuming one frees exactly one slot.
	b.MustClaim(1, 10)
	if _, err := b.Schedule(alice, "", 0, 10, 0); err != nil {
		t.Fatalf("Schedule after Claim: %v", err)
	}
	if _, err := b.Schedule(alice, "", 0, 10, 0); err != ErrBookFull {
		t.Fatalf("cap not re-applied: got %v, want ErrBookFull", err)
	}
}

// --- the central claim: exactly-once ---------------------------------------

func TestClaimSucceedsExactlyOnce(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "do-the-thing", 0, 10, 0)

	d, err := b.Claim(id, 10)
	if err != nil {
		t.Fatalf("first Claim: %v", err)
	}
	if d.Payload != "do-the-thing" {
		t.Errorf("payload = %q", d.Payload)
	}
	for i := 0; i < 5; i++ {
		if _, err := b.Claim(id, 10); err != ErrNotFound {
			t.Fatalf("replay %d: got %v, want ErrNotFound", i, err)
		}
	}
}

func TestIDsAreNeverReused(t *testing.T) {
	b := newBook(t)
	id1 := b.MustSchedule(alice, "", 0, 10, 0)
	b.MustClaim(id1, 10)
	if b.OpenCount() != 0 {
		t.Fatalf("OpenCount = %d after claim", b.OpenCount())
	}
	// The book is empty again, but the next ID must still move forward.
	id2 := b.MustSchedule(alice, "", 0, 10, 0)
	if id2 == id1 {
		t.Fatalf("ID %d reused after the book emptied", id2)
	}
	// So the old ID stays permanently unclaimable.
	if _, err := b.Claim(id1, 10); err != ErrNotFound {
		t.Errorf("old ID claimable again: %v", err)
	}
}

func TestConsumedByAnyPathStaysConsumed(t *testing.T) {
	// Every terminal path must close the ID to all three transitions.
	paths := []struct {
		name    string
		consume func(b *Book, id uint64)
	}{
		{"claim", func(b *Book, id uint64) { b.MustClaim(id, 10) }},
		{"cancel", func(b *Book, id uint64) { b.MustCancel(id, alice) }},
		{"expire", func(b *Book, id uint64) { b.MustExpire(id, 100) }},
	}
	for _, p := range paths {
		b := newBook(t)
		id := b.MustSchedule(alice, "", 0, 10, 50) // due 10, expires 60
		p.consume(b, id)

		if _, err := b.Claim(id, 10); err != ErrNotFound {
			t.Errorf("%s then Claim: got %v, want ErrNotFound", p.name, err)
		}
		if _, err := b.Cancel(id, alice); err != ErrNotFound {
			t.Errorf("%s then Cancel: got %v, want ErrNotFound", p.name, err)
		}
		if _, err := b.Expire(id, 100); err != ErrNotFound {
			t.Errorf("%s then Expire: got %v, want ErrNotFound", p.name, err)
		}
		if _, ok := b.Get(id); ok {
			t.Errorf("%s: deferral still visible", p.name)
		}
	}
}

// --- the claim window -----------------------------------------------------

func TestClaimWindowIsHalfOpen(t *testing.T) {
	// Schedule at 0, delay 10, ttl 5 => claimable on [10, 15).
	cases := []struct {
		now  int64
		want error
	}{
		{0, ErrNotDue},
		{9, ErrNotDue},
		{10, nil}, // due instant is claimable
		{14, nil},
		{15, ErrExpired}, // expiry instant is NOT claimable
		{16, ErrExpired},
	}
	for _, c := range cases {
		b := newBook(t)
		id := b.MustSchedule(alice, "", 0, 10, 5)
		_, err := b.Claim(id, c.now)
		if err != c.want {
			t.Errorf("Claim at now=%d: got %v, want %v", c.now, err, c.want)
		}
		// A refused Claim must not consume the deferral.
		if c.want != nil {
			if _, ok := b.Get(id); !ok {
				t.Errorf("refused Claim at now=%d consumed the deferral", c.now)
			}
		}
	}
}

func TestClaimRejectsNegativeNow(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 0)
	if _, err := b.Claim(id, -1); err != ErrInvalidNow {
		t.Fatalf("got %v, want ErrInvalidNow", err)
	}
	if _, ok := b.Get(id); !ok {
		t.Error("negative now consumed the deferral")
	}
}

func TestClaimUnknownID(t *testing.T) {
	b := newBook(t)
	if _, err := b.Claim(999, 10); err != ErrNotFound {
		t.Fatalf("got %v, want ErrNotFound", err)
	}
}

// --- cancellation ---------------------------------------------------------

func TestCancelOwnerOnly(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 0)

	if _, err := b.Cancel(id, bob); err != ErrNotOwner {
		t.Fatalf("bob cancelling alice's deferral: got %v, want ErrNotOwner", err)
	}
	if _, ok := b.Get(id); !ok {
		t.Fatal("refused Cancel consumed the deferral")
	}
	if _, err := b.Cancel(id, ""); err != ErrEmptyOwner {
		t.Errorf("empty owner: got %v, want ErrEmptyOwner", err)
	}
	if _, err := b.Cancel(id, alice); err != nil {
		t.Fatalf("owner cancel: %v", err)
	}
}

func TestCancelWorksAfterDue(t *testing.T) {
	// Cancellation is allowed while OPEN, not only while pending — an owner
	// can still pull a deferral back after it became claimable, as long as
	// nobody claimed it first.
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 0)
	if _, err := b.Cancel(id, alice); err != nil {
		t.Fatalf("cancel after due: %v", err)
	}
}

func TestCancelLosesRaceToClaim(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 0)
	b.MustClaim(id, 10)
	if _, err := b.Cancel(id, alice); err != ErrNotFound {
		t.Fatalf("cancel after claim: got %v, want ErrNotFound", err)
	}
}

// --- expiry ---------------------------------------------------------------

func TestExpireRequiresExpiry(t *testing.T) {
	b := newBook(t)
	// Not yet expired.
	id := b.MustSchedule(alice, "", 0, 10, 5) // expires 15
	if _, err := b.Expire(id, 14); err != ErrNotExpired {
		t.Errorf("at 14: got %v, want ErrNotExpired", err)
	}
	if _, err := b.Expire(id, 15); err != nil {
		t.Errorf("at 15: %v", err)
	}

	// ttl == 0 can never be expired away.
	never := b.MustSchedule(alice, "", 0, 10, 0)
	if _, err := b.Expire(never, 1<<62); err != ErrNotExpired {
		t.Errorf("no-expiry deferral: got %v, want ErrNotExpired", err)
	}
}

func TestExpireIsPermissionless(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "", 0, 10, 5)
	// No owner argument at all — anyone may clear a dead entry.
	if _, err := b.Expire(id, 20); err != nil {
		t.Fatalf("Expire: %v", err)
	}
}

func TestExpiredDeferralCannotBeClaimedOrGriefTheCap(t *testing.T) {
	b, _ := New(0, 100, 1)
	id := b.MustSchedule(alice, "", 0, 10, 5) // expires 15
	// Cap is full and the entry is dead.
	if _, err := b.Schedule(bob, "", 20, 10, 0); err != ErrBookFull {
		t.Fatalf("got %v, want ErrBookFull", err)
	}
	if _, err := b.Claim(id, 20); err != ErrExpired {
		t.Fatalf("got %v, want ErrExpired", err)
	}
	// Anyone can unstick it.
	b.MustExpire(id, 20)
	if _, err := b.Schedule(bob, "", 20, 10, 0); err != nil {
		t.Fatalf("Schedule after Expire: %v", err)
	}
}

// --- queries --------------------------------------------------------------

func TestDueReturnsOnlyClaimableInIDOrder(t *testing.T) {
	b := newBook(t)
	b.MustSchedule(alice, "a", 0, 10, 0)  // 1: due 10
	b.MustSchedule(alice, "b", 0, 500, 0) // 2: due 500, not yet
	b.MustSchedule(alice, "c", 0, 10, 5)  // 3: due 10, expired at 15
	b.MustSchedule(alice, "d", 0, 20, 0)  // 4: due 20

	got := b.Due(20, 10)
	if len(got) != 2 {
		t.Fatalf("Due returned %d entries, want 2", len(got))
	}
	if got[0].ID != 1 || got[1].ID != 4 {
		t.Errorf("IDs = %d,%d; want 1,4", got[0].ID, got[1].ID)
	}
}

func TestDueRespectsLimit(t *testing.T) {
	b := newBook(t)
	for i := 0; i < 5; i++ {
		b.MustSchedule(alice, "", 0, 10, 0)
	}
	if got := b.Due(10, 2); len(got) != 2 {
		t.Errorf("limit 2 returned %d", len(got))
	}
	if got := b.Due(10, 0); len(got) != 0 {
		t.Errorf("limit 0 returned %d", len(got))
	}
	if got := b.Due(10, -1); len(got) != 0 {
		t.Errorf("limit -1 returned %d", len(got))
	}
}

func TestExpirable(t *testing.T) {
	b := newBook(t)
	b.MustSchedule(alice, "", 0, 10, 5) // 1: expires 15
	b.MustSchedule(alice, "", 0, 10, 0) // 2: never expires
	b.MustSchedule(alice, "", 0, 10, 5) // 3: expires 15

	got := b.Expirable(15, 10)
	if len(got) != 2 || got[0].ID != 1 || got[1].ID != 3 {
		t.Fatalf("Expirable = %v", got)
	}
	if len(b.Expirable(14, 10)) != 0 {
		t.Error("Expirable before expiry returned entries")
	}
}

func TestIterateOpenIsIDOrdered(t *testing.T) {
	b, _ := New(0, 100, 32)
	// Schedule enough to cross the 1->2 digit boundary, where naive string
	// keys would order "10" before "9".
	for i := 0; i < 12; i++ {
		b.MustSchedule(alice, "", 0, 1, 0)
	}
	prev := uint64(0)
	n := 0
	b.IterateOpen(func(d Deferral) bool {
		if d.ID <= prev {
			t.Fatalf("out of order: %d after %d", d.ID, prev)
		}
		prev = d.ID
		n++
		return false
	})
	if n != 12 {
		t.Errorf("iterated %d, want 12", n)
	}
}

func TestGetReturnsACopy(t *testing.T) {
	b := newBook(t)
	id := b.MustSchedule(alice, "original", 0, 10, 0)
	d, _ := b.Get(id)
	d.Payload = "tampered"
	d.Owner = bob

	again, _ := b.Get(id)
	if again.Payload != "original" || again.Owner != alice {
		t.Fatalf("mutating a returned Deferral changed the book: %+v", again)
	}
}

// --- helpers --------------------------------------------------------------

func TestIDKeyOrdering(t *testing.T) {
	if idKey(9) >= idKey(10) {
		t.Errorf("idKey(9)=%q not < idKey(10)=%q", idKey(9), idKey(10))
	}
	if len(idKey(1)) != 20 {
		t.Errorf("idKey(1) width = %d, want 20", len(idKey(1)))
	}
	// Largest uint64 is exactly 20 digits and must not be truncated.
	const maxU64 = ^uint64(0)
	if got := idKey(maxU64); got != "18446744073709551615" {
		t.Errorf("idKey(max) = %q", got)
	}
	if idKey(maxU64-1) >= idKey(maxU64) {
		t.Error("ordering breaks at the top of the range")
	}
}

func TestCheckedAdd(t *testing.T) {
	const max = int64(1<<63 - 1)
	const min = int64(-1 << 63)
	if _, ok := checkedAdd(max, 1); ok {
		t.Error("max+1 reported ok")
	}
	if _, ok := checkedAdd(min, -1); ok {
		t.Error("min-1 reported ok")
	}
	if v, ok := checkedAdd(5, 7); !ok || v != 12 {
		t.Errorf("5+7 = %d,%v", v, ok)
	}
}

func TestDeferralPredicates(t *testing.T) {
	d := Deferral{DueAt: 10, ExpiresAt: 20}
	if d.IsDue(9) || !d.IsDue(10) {
		t.Error("IsDue boundary")
	}
	if d.IsExpired(19) || !d.IsExpired(20) {
		t.Error("IsExpired boundary")
	}
	if d.IsClaimable(9) || !d.IsClaimable(10) || !d.IsClaimable(19) || d.IsClaimable(20) {
		t.Error("IsClaimable window")
	}
}

// Package permbook is a bounded, authorization-carrying facade over
// gno.land/p/nt/groups/v0. It lets a realm define named permissions, grant
// them to addresses, revoke them, and ask "does this address currently hold
// this permission" without iterating anything.
//
// It holds no coins, imports no banker, stores no callbacks, and owns no
// package-level state. The importing realm allocates a *Book and keeps it
// private.
//
// # What this package adds, and what it does not
//
// It adds exactly four things to groups, and deliberately nothing else:
//
//  1. an ADMIN bound to the book, with a two-step handoff;
//  2. BOUNDS on permission count, holders per permission, and name shape;
//  3. permission semantics instead of membership semantics — no base set, no
//     metadata slot, and an empty permission is pruned rather than kept;
//  4. a cross-realm surface that is safe by CONSTRUCTION — the *groups.Group
//     is unexported and no method returns a mutable handle to it.
//
// Everything else — the B+-tree registry, the member sets, ordered
// iteration, the readonly views — comes from groups. This package writes no
// data-structure code.
//
// # The query
//
//	if !book.Has("withdraw", who) {
//		panic("not authorized")
//	}
//
// Has costs two independent B+-tree descents: O(log P) to find the
// permission, O(log H) to find the holder. It is NOT a function of how many
// permissions `who` already holds. That matters: every other named-permission
// implementation surveyed answers this by iterating the subject's
// permissions, which makes the most-privileged address the most expensive to
// check — the wrong asymptotic for an authorization check on a hot path.
//
// # Authorization
//
// Mutators take (_ int, rlm realm) and identify the principal as
// rlm.Previous().Address(), after asserting rlm.IsCurrent(). The consuming
// realm threads its own cur:
//
//	func Grant(cur realm, perm string, addr address) {
//		if err := book.Grant(0, cur, perm, addr); err != nil {
//			panic(err)
//		}
//	}
//
// IsCurrent() rejects a stale or stashed realm value, so a hostile realm
// cannot replay an old cur to impersonate the admin. This is the same shape
// as p/nt/ownable/v0 and p/nt/ownable/v0/exts/authorizable.
//
// # Lifecycle of a permission
//
// A permission comes into existence on its first grant and ceases to exist
// when its last holder is revoked. There is no create step and no reserved
// name. Has returns false either way, so the distinction is invisible to a
// caller and the book does not accumulate empty buckets.
//
//	(absent) ──Grant──> held by 1..MaxHoldersPerPermission ──Revoke last──> (absent)
//	                              │
//	                              └── DropPermission ──> (absent)
//
// # Admin handoff is two-step
//
// NominateAdmin records a nominee; only AcceptAdmin, called by that nominee,
// moves the admin. A one-step transfer to a well-formed-but-unowned address
// is permanently fatal — address.IsValid only checks bech32 form, so a
// mistyped address passes validation and leaves a book nobody can ever grant
// or revoke on again. This is the Y4 finding from the audit of Cosmic Bull's
// own r/permission_registry, carried forward.
//
// # Consumer contract — the parts this package CANNOT enforce
//
//  1. THREAD A LIVE cur. rlm.IsCurrent() proves the realm value came from a
//     live crossing frame, and rlm.Previous().Address() is then the principal
//     that crossed into your realm. A consumer that wraps a permbook mutator
//     in a NON-crossing exported helper resolves its importer's caller
//     instead of its importer — Class-2 designation forgery, in the consumer.
//     Call permbook mutators from your own crossing entrypoints, passing that
//     entrypoint's own cur.
//
//  2. DO NOT LEAK THE *Book. No method here returns a mutable handle, but a
//     consumer that exports its *Book — or returns it from a function
//     reachable by another realm — hands out every mutator on it, and
//     borrow rule #2 commits those writes under YOUR realm's authority. Keep
//     it in an unexported package-level variable.
//
//  3. Has ANSWERS ABOUT AN ADDRESS, NOT ABOUT YOUR CALLER. It performs no
//     authentication. Derive the address from your own crossing entrypoint's
//     cur.Previous().Address() and pass it in.
//
//  4. CHOOSE LIMITS DELIBERATELY. They are fixed for the life of a Book. A
//     consumer that needs different bounds later must allocate a second Book;
//     nothing here migrates state between them.
//
// # Note on the groups base set
//
// A groups.Group carries a base address set alongside its named roles. This
// package never writes to it, so it is provably empty for any Book, and
// "in the base set" can never mean "holds a permission".
package permbook

import (
	"errors"

	"gno.land/p/nt/groups/v0"
)

// Ceilings on what Limits may be configured to. They bound worst-case gas
// and storage for any Book, however the consumer configures it.
//
// MaxPermissionsCeiling is the one that bounds GAS rather than merely
// storage. Three operations walk every permission in the book at O(P log H)
// — Permissions, HasAny, and RevokeAll — and this ceiling is what bounds
// them. Everything else is logarithmic or paginated; see each method's own
// doc for its cost, which is authoritative.
//
// In particular HasAny is NOT a cheap variant of Has. Has is two tree
// descents; HasAny is a full walk of the registry. Do not put HasAny on a
// hot authorization path or inside a per-item render loop.
//
// These ceilings are not the objection this package raises against a shared
// registry. A shared registry's caps are rivalrous and unraisable because
// one immutable realm holds every tenant's state; here a consumer that needs
// more simply allocates another Book in its own realm, at no cost to anyone
// else.
const (
	MaxPermissionsCeiling = 256
	MaxHoldersCeiling     = 10000
	MaxNameLenCeiling     = 64
)

// Default limits, used by NewDefault.
const (
	DefaultMaxPermissions          = 64
	DefaultMaxHoldersPerPermission = 1024
	DefaultMaxNameLen              = 32
)

var (
	ErrUnauthorized      = errors.New("permbook: caller is not the admin")
	ErrNotLiveRealm      = errors.New("permbook: rlm is not the caller's live cur")
	ErrInvalidAddress    = errors.New("permbook: invalid address")
	ErrInvalidName       = errors.New("permbook: permission name must be 1..MaxNameLen chars, lowercase alphanumeric and underscore only")
	ErrInvalidLimits     = errors.New("permbook: limits must be positive and within the package ceilings")
	ErrAlreadyGranted    = errors.New("permbook: address already holds this permission")
	ErrNotGranted        = errors.New("permbook: address does not hold this permission")
	ErrPermissionLimit   = errors.New("permbook: permission limit reached for this book")
	ErrHolderLimit       = errors.New("permbook: holder limit reached for this permission")
	ErrNoPendingAdmin    = errors.New("permbook: no pending admin nomination")
	ErrNotPendingAdmin   = errors.New("permbook: caller is not the pending admin")
	ErrSameAdmin         = errors.New("permbook: nominee is already the admin")
	ErrUnknownPermission = errors.New("permbook: no such permission")
)

// Limits are fixed at construction and never change for the life of a Book.
type Limits struct {
	// MaxPermissions bounds how many distinct permission names may exist at
	// once. Because Permissions and RevokeAll walk all of them, this bounds
	// gas, not just storage.
	MaxPermissions int

	// MaxHoldersPerPermission bounds how many addresses may hold any one
	// permission. No operation iterates holders unpaginated, so this bounds
	// storage rather than gas.
	MaxHoldersPerPermission int

	// MaxNameLen bounds permission-name length.
	MaxNameLen int
}

// DefaultLimits returns the limits used by NewDefault.
func DefaultLimits() Limits {
	return Limits{
		MaxPermissions:          DefaultMaxPermissions,
		MaxHoldersPerPermission: DefaultMaxHoldersPerPermission,
		MaxNameLen:              DefaultMaxNameLen,
	}
}

func (l Limits) valid() bool {
	return l.MaxPermissions > 0 && l.MaxPermissions <= MaxPermissionsCeiling &&
		l.MaxHoldersPerPermission > 0 && l.MaxHoldersPerPermission <= MaxHoldersCeiling &&
		l.MaxNameLen > 0 && l.MaxNameLen <= MaxNameLenCeiling
}

// Book is a bounded set of named permissions with an admin. The zero value
// is not usable; construct with New or NewDefault.
//
// SECURITY: keep a *Book in an unexported variable. It is the capability.
// Every mutator on it is gated on the admin, but a realm that receives the
// pointer itself can invoke those mutators, and borrow rule #2 commits the
// writes under the ALLOCATING realm's authority.
type Book struct {
	g            *groups.Group
	admin        address
	pendingAdmin address
	lim          Limits
}

// New constructs an empty Book owned by admin, with explicit limits.
func New(admin address, lim Limits) (*Book, error) {
	if !admin.IsValid() {
		return nil, ErrInvalidAddress
	}
	if !lim.valid() {
		return nil, ErrInvalidLimits
	}
	return &Book{
		g:     groups.NewGroup(),
		admin: admin,
		lim:   lim,
	}, nil
}

// NewDefault constructs an empty Book owned by admin, with DefaultLimits.
func NewDefault(admin address) (*Book, error) {
	return New(admin, DefaultLimits())
}

// --- authorization ---

// principal returns the address that crossed into the caller's realm, after
// proving rlm is a live crossing frame rather than a stashed value.
func principal(_ int, rlm realm) (address, error) {
	if !rlm.IsCurrent() {
		return address(""), ErrNotLiveRealm
	}
	return rlm.Previous().Address(), nil
}

// assertAdmin resolves the principal from rlm and requires it to be the
// book's admin.
func (b *Book) assertAdmin(_ int, rlm realm) error {
	who, err := principal(0, rlm)
	if err != nil {
		return err
	}
	if who != b.admin {
		return ErrUnauthorized
	}
	return nil
}

// --- grant and revoke ---

// Grant gives addr the named permission. Admin only.
//
// The permission is created if it does not exist. Granting a permission the
// address already holds returns ErrAlreadyGranted rather than silently
// succeeding, so a consumer cannot mistake a no-op for a state change.
func (b *Book) Grant(_ int, rlm realm, perm string, addr address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.validName(perm) {
		return ErrInvalidName
	}
	if !addr.IsValid() {
		return ErrInvalidAddress
	}

	r, found := b.g.GetRole(perm)
	if !found {
		if b.g.RoleCount() >= b.lim.MaxPermissions {
			return ErrPermissionLimit
		}
		var err error
		r, err = b.g.AddRole(perm)
		if err != nil {
			return err
		}
	}

	members := r.Members()
	if members.Has(addr) {
		return ErrAlreadyGranted
	}
	if members.Size() >= b.lim.MaxHoldersPerPermission {
		// No rollback is needed here, and adding one would be dead code.
		//
		// Reaching this branch requires Size() >= MaxHoldersPerPermission,
		// and Limits.valid guarantees MaxHoldersPerPermission >= 1, so
		// Size() >= 1. A permission created moments ago above has Size() 0
		// and therefore cannot reach this branch at all. So the permission
		// this rejects always pre-existed with holders, and returning leaves
		// no orphan empty bucket occupying a MaxPermissions slot.
		//
		// That argument depends on Limits.valid rejecting a zero holder
		// limit. If that ever changes, this branch needs an undo.
		return ErrHolderLimit
	}

	members.Add(addr)
	return nil
}

// Revoke removes the named permission from addr. Admin only.
//
// Revoking the last holder removes the permission itself, freeing its slot
// against MaxPermissions. Has reports false either way, so this is invisible
// to a caller and keeps the book from accumulating empty buckets.
func (b *Book) Revoke(_ int, rlm realm, perm string, addr address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.revokeOne(perm, addr) {
		return ErrNotGranted
	}
	return nil
}

// revokeOne removes addr from perm and prunes the permission if it is left
// empty. Reports whether addr actually held it. No authorization: every
// caller is inside this package and has already gated on the admin.
func (b *Book) revokeOne(perm string, addr address) bool {
	r, found := b.g.GetRole(perm)
	if !found {
		return false
	}
	members := r.Members()
	if !members.Remove(addr) {
		return false
	}
	if members.Size() == 0 {
		b.g.RemoveRole(perm)
	}
	return true
}

// RevokeAll removes addr from every permission in the book and reports how
// many were removed. Admin only.
//
// Cost is O(P log H) in the book's permission count — bounded by
// MaxPermissions, which is why that limit has a ceiling.
//
// Implementation note: the permission names are collected FIRST, into a
// value slice, and the registry is mutated only after that walk returns.
// groups documents that mutating the role registry mid-iteration can panic
// and abort the transaction.
func (b *Book) RevokeAll(_ int, rlm realm, addr address) (int, error) {
	if err := b.assertAdmin(0, rlm); err != nil {
		return 0, err
	}
	names := b.g.RolesContaining(addr)
	n := 0
	for _, perm := range names {
		if b.revokeOne(perm, addr) {
			n++
		}
	}
	return n, nil
}

// DropPermission removes a permission and every grant of it. Admin only.
//
// Cost is O(log P): groups discards the whole member set with the role and
// does not walk it, so this is safe for a permission with many holders.
func (b *Book) DropPermission(_ int, rlm realm, perm string) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.g.RemoveRole(perm) {
		return ErrUnknownPermission
	}
	return nil
}

// --- admin handoff ---

// NominateAdmin records a nominee for the admin role. Admin only. The
// handoff does NOT take effect until the nominee calls AcceptAdmin, and a
// nomination may be withdrawn with CancelNomination until then.
func (b *Book) NominateAdmin(_ int, rlm realm, nominee address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !nominee.IsValid() {
		return ErrInvalidAddress
	}
	if nominee == b.admin {
		return ErrSameAdmin
	}
	b.pendingAdmin = nominee
	return nil
}

// CancelNomination withdraws a pending nomination. Admin only.
func (b *Book) CancelNomination(_ int, rlm realm) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if b.pendingAdmin == address("") {
		return ErrNoPendingAdmin
	}
	b.pendingAdmin = address("")
	return nil
}

// AcceptAdmin completes a pending handoff. Only the nominee may call it.
func (b *Book) AcceptAdmin(_ int, rlm realm) error {
	who, err := principal(0, rlm)
	if err != nil {
		return err
	}
	if b.pendingAdmin == address("") {
		return ErrNoPendingAdmin
	}
	if who != b.pendingAdmin {
		return ErrNotPendingAdmin
	}
	b.admin = who
	b.pendingAdmin = address("")
	return nil
}

// --- queries ---
//
// Queries perform NO caller authentication. They answer questions about an
// address, not about your caller. See consumer-contract clause 3.

// Has reports whether addr currently holds the named permission.
//
// Two B+-tree descents, O(log P + log H). Independent of how many other
// permissions addr holds. Never panics; unknown permissions report false.
func (b *Book) Has(perm string, addr address) bool {
	r, found := b.g.GetRole(perm)
	if !found {
		return false
	}
	return r.Members().Has(addr)
}

// HasAny reports whether addr holds any permission at all. O(P log H).
func (b *Book) HasAny(addr address) bool {
	return b.g.HasAny(addr)
}

// Permissions returns the names addr holds, in lexicographic order, or nil.
// O(P log H) — bounded by MaxPermissions.
func (b *Book) Permissions(addr address) []string {
	return b.g.RolesContaining(addr)
}

// PermissionCount returns how many distinct permissions currently exist.
func (b *Book) PermissionCount() int {
	return b.g.RoleCount()
}

// PermissionNames returns up to count permission names in lexicographic
// order, starting at offset. Paginated so the caller, not the book, chooses
// how much work a single call does.
func (b *Book) PermissionNames(offset, count int) []string {
	if count <= 0 {
		return nil
	}
	var out []string
	b.g.IterateRoles(offset, count, func(rr *groups.ReadonlyRole) bool {
		out = append(out, rr.Name())
		return false
	})
	return out
}

// HolderCount returns how many addresses hold the named permission, or 0 if
// it does not exist.
func (b *Book) HolderCount(perm string) int {
	r, found := b.g.GetRole(perm)
	if !found {
		return 0
	}
	return r.Members().Size()
}

// Holders returns up to count holders of the named permission, in sorted
// order, starting at offset. Paginated for the same reason as
// PermissionNames. Returns nil for an unknown permission.
func (b *Book) Holders(perm string, offset, count int) []address {
	if count <= 0 {
		return nil
	}
	r, found := b.g.GetRole(perm)
	if !found {
		return nil
	}
	var out []address
	r.Members().IterateByOffset(offset, count, func(a address) bool {
		out = append(out, a)
		return false
	})
	return out
}

// Admin returns the book's current admin.
func (b *Book) Admin() address {
	return b.admin
}

// PendingAdmin returns the nominated-but-not-yet-accepted admin, or the
// empty address if there is no pending nomination.
func (b *Book) PendingAdmin() address {
	return b.pendingAdmin
}

// IsAdmin reports whether addr is the book's admin.
func (b *Book) IsAdmin(addr address) bool {
	return addr == b.admin
}

// Limits returns the book's fixed limits.
func (b *Book) Limits() Limits {
	return b.lim
}

// --- names ---

// validName restricts permission names to lowercase alphanumerics and
// underscores, within the book's MaxNameLen.
//
// Beyond hygiene this is a security property: permission names end up in
// composite trust decisions and in rendered output, so no delimiter,
// whitespace, or markdown character may enter one.
func (b *Book) validName(name string) bool {
	if name == "" || len(name) > b.lim.MaxNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

package permbook

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	admin   = testutils.TestAddress("permadmin")
	nominee = testutils.TestAddress("nominee")
	alice   = testutils.TestAddress("alice")
	bob     = testutils.TestAddress("bob")
	mallory = testutils.TestAddress("mallory")
)

// --- test harness ---
//
// permbook's mutators identify their principal as rlm.Previous().Address()
// after proving rlm.IsCurrent(). A test function's own `cur` is current but
// has no previous frame — Previous() panics with "cannot seek beyond origin
// caller override". So every mutating call is made from inside a real
// crossing frame, entered with cross(cur), exactly as p/nt/ownable/v0's own
// tests do.
//
// testing.SetRealm(testing.NewUserRealm(addr)) sets the current realm to a
// user realm for addr, so the next crossing frame has
// Previous().Address() == addr — the principal the mutator authorizes
// against. It is written out at every call site on purpose: the override is
// scoped to the frame that installs it, so wrapping it in a helper makes it
// pop the moment the helper returns and the principal comes back empty.

func grant(cur realm, b *Book, perm string, addr address) error {
	var err error
	func(cur realm) { err = b.Grant(0, cur, perm, addr) }(cross(cur))
	return err
}

func revoke(cur realm, b *Book, perm string, addr address) error {
	var err error
	func(cur realm) { err = b.Revoke(0, cur, perm, addr) }(cross(cur))
	return err
}

func revokeAll(cur realm, b *Book, addr address) (int, error) {
	var (
		n   int
		err error
	)
	func(cur realm) { n, err = b.RevokeAll(0, cur, addr) }(cross(cur))
	return n, err
}

func dropPerm(cur realm, b *Book, perm string) error {
	var err error
	func(cur realm) { err = b.DropPermission(0, cur, perm) }(cross(cur))
	return err
}

func nominate(cur realm, b *Book, addr address) error {
	var err error
	func(cur realm) { err = b.NominateAdmin(0, cur, addr) }(cross(cur))
	return err
}

func cancelNom(cur realm, b *Book) error {
	var err error
	func(cur realm) { err = b.CancelNomination(0, cur) }(cross(cur))
	return err
}

func acceptAdmin(cur realm, b *Book) error {
	var err error
	func(cur realm) { err = b.AcceptAdmin(0, cur) }(cross(cur))
	return err
}

// newBook builds a book for tests.
func newBook(t *testing.T, owner address) *Book {
	t.Helper()
	b, err := NewDefault(owner)
	uassert.NoError(t, err)
	if b == nil {
		t.Fatal("NewDefault returned nil book")
	}
	return b
}

// --- construction ---

func TestNewDefault(cur realm, t *testing.T) {
	b := newBook(t, admin)
	uassert.Equal(t, admin.String(), b.Admin().String())
	uassert.Equal(t, "", b.PendingAdmin().String())
	uassert.Equal(t, 0, b.PermissionCount())
	uassert.True(t, b.IsAdmin(admin))
	uassert.False(t, b.IsAdmin(alice))

	l := b.Limits()
	uassert.Equal(t, DefaultMaxPermissions, l.MaxPermissions)
	uassert.Equal(t, DefaultMaxHoldersPerPermission, l.MaxHoldersPerPermission)
	uassert.Equal(t, DefaultMaxNameLen, l.MaxNameLen)
}

func TestNewRejectsInvalidAdmin(cur realm, t *testing.T) {
	b, err := NewDefault(address(""))
	uassert.ErrorIs(t, err, ErrInvalidAddress)
	uassert.True(t, b == nil)

	b, err = NewDefault(address("not-a-bech32-address"))
	uassert.ErrorIs(t, err, ErrInvalidAddress)
	uassert.True(t, b == nil)
}

func TestNewRejectsInvalidLimits(cur realm, t *testing.T) {
	cases := []Limits{
		{MaxPermissions: 0, MaxHoldersPerPermission: 10, MaxNameLen: 10},
		{MaxPermissions: 10, MaxHoldersPerPermission: 0, MaxNameLen: 10},
		{MaxPermissions: 10, MaxHoldersPerPermission: 10, MaxNameLen: 0},
		{MaxPermissions: -1, MaxHoldersPerPermission: 10, MaxNameLen: 10},
		{MaxPermissions: MaxPermissionsCeiling + 1, MaxHoldersPerPermission: 10, MaxNameLen: 10},
		{MaxPermissions: 10, MaxHoldersPerPermission: MaxHoldersCeiling + 1, MaxNameLen: 10},
		{MaxPermissions: 10, MaxHoldersPerPermission: 10, MaxNameLen: MaxNameLenCeiling + 1},
	}
	for i, lim := range cases {
		b, err := New(admin, lim)
		uassert.ErrorIs(t, err, ErrInvalidLimits)
		if b != nil {
			t.Errorf("case %d: expected nil book", i)
		}
	}
